-- =============================================================================
-- StaziaMed, CARGA DAS PROVAS CORRIGIDAS, parte 2 (Revalida 2022/1, revalida-2022-1): texto fiel ao caderno oficial do Inep.
-- Gerado por scripts/carga-provas/gerar-correcoes.mjs (ramo carga-provas). Não edite à mão.
-- O que faz: 442 correções de texto em 100 questões (397 campos: enunciado ou alternativa).
--   * Cada campo só é trocado se o texto no banco ainda é EXATAMENTE o de 12/10/2026 (o que a revisão comparou com o PDF).
--     Se alguém mudou esse texto depois, o campo é PULADO e aparece na lista do fim. Nada é apagado.
--   * O texto antigo fica no histórico da questão (Administração > Questões > Editar > Ver histórico de mudanças), com o motivo.
--   * NÃO mexe em gabarito, situação (anulada), explicações, conduta esperada, "o que a questão avalia", tema, figuras.
--   * Regra do sistema (migração 9500): se a questão tinha Análise Stazia publicada, ela sai do ar (explicava o texto antigo);
--     a contagem aparece no fim.
-- Como colar: editor SQL do Supabase, o arquivo INTEIRO, Run. A primeira linha do resultado começa com "OK:" (ou "ATENÇÃO:" se
-- algum campo foi pulado; mostre ao Claude). Pode colar de novo: a segunda vez não muda nada.
-- =============================================================================
create temp table if not exists _carga_texto_resultado (prova text, questao text, codigo text, campo text, situacao text);
delete from _carga_texto_resultado where prova = 'revalida-2022-1';

do $carga_texto$
declare
  v_dados constant jsonb := $carga_dados$[{"id":"revalida_2022_1_q001","code":"REV-2022.1-Q001","campos":{"A":{"antes_md5":"75f100d9c5e6d1c9759b061c96e60c76","depois":"oxacilina."},"B":{"antes_md5":"acdf69257ef88f11183c93a3ff91d24f","depois":"cefalexina."},"C":{"antes_md5":"d34d79b6a10377a19526557d4a56d6f5","depois":"clindamicina."},"D":{"antes_md5":"049a2b5933a496694f58c380804f5010","depois":"levofloxacina."}}},{"id":"revalida_2022_1_q002","code":"REV-2022.1-Q002","campos":{"A":{"antes_md5":"b39b7644622dfa2c608463e80e326ddd","depois":"Coledocolitíase."},"B":{"antes_md5":"5dfdbe3c09306c8397a94f2e922affbe","depois":"Adenocarcinoma de vesícula biliar."},"C":{"antes_md5":"230adb80ff657d634aee6ce112a83ce1","depois":"Adenocarcinoma de cabeça de pâncreas."},"D":{"antes_md5":"774384e804e6d796e7eba64c97119997","depois":"Colangiocarcinoma da confluência dos ductos hepáticos."}}},{"id":"revalida_2022_1_q003","code":"REV-2022.1-Q003","campos":{"statement":{"antes_md5":"107c64dc98765f02952ef0a15c2790c6","depois":"Um menino com 5 anos de idade, acompanhado da mãe, é atendido em unidade de saúde. A mãe relata o aparecimento abrupto de manchas arroxeadas indolores nos membros inferiores da criança há 2 dias, sem outras queixas. Há 1 mês, conta que o filho apresentou quadro de resfriado comum, para o qual fez uso somente de soro fisiológico para lavagem nasal. Nega uso recente de medicamentos ou antecedentes familiares relevantes. Ao exame clínico, o menino apresenta regular estado geral, corado, hidratado, anictérico, acianótico, afebril e eupneico; baço palpável ao nível de rebordo costal esquerdo, presença de petéquias e equimoses indolores em membros inferiores. Exame de Fundo de Olho sem sinais de sangramento. Sem evidência de outros sangramentos ou outros achados clínicos relevantes. Os exames laboratoriais iniciais evidenciaram hemoglobina de 12,3 g/dL (valor de referência [VR]: 12,6 g/dL); hematócrito de 38% (VR: 37%); contagem de 5.700 leucócitos/mm³ (VR: 5.000-15.000/mm³), com 37% de segmentados, 44% de linfócitos, 1% de monócitos e contagem de plaquetas de 64.000/mm3 (VR: 150.000-450.000/mm³). Coagulograma com um tempo de tromboplastina de 12,5 segundos (VR: 10-14 segundos), 100% de atividade de protrombina e um tempo de tromboplastina ativada de 31 segundos (VR: 25-36 segundos). Considerando a principal hipótese diagnóstica para esse caso, qual deve ser a conduta terapêutica inicial?"},"A":{"antes_md5":"6855e0b592ca0a559189250974283363","depois":"Terapia com corticosteroide."},"B":{"antes_md5":"5e6c8dc5509f55b275021ca93e26cc78","depois":"Internação para esplenectomia."},"C":{"antes_md5":"0efd669bf949e35b1dc1c690fb440cd7","depois":"Observação clínica ambulatorial."},"D":{"antes_md5":"215950f3fc7a7bc8e2eef3ee57841a90","depois":"Administração de imunoglobulina."}}},{"id":"revalida_2022_1_q004","code":"REV-2022.1-Q004","campos":{"A":{"antes_md5":"4d8911b5b9924c4fe1dca2bd2a7ef063","depois":"45 aos 69 anos de idade; anualmente."},"B":{"antes_md5":"713155e16db6f47851a9418e18dc6429","depois":"50 aos 79 anos de idade; anualmente."},"C":{"antes_md5":"410b50192d589a7c171cad74cd2c7f81","depois":"40 aos 69 anos de idade; a cada 2 anos."},"D":{"antes_md5":"ec48032d492d39586f195b076dc8fd08","depois":"50 aos 69 anos de idade; a cada 2 anos."}}},{"id":"revalida_2022_1_q005","code":"REV-2022.1-Q005","campos":{"statement":{"antes_md5":"fb6da4588dacf030916db86b27cac2df","depois":"Um homem com 48 anos de idade é obeso, tabagista e hipertenso há 6 anos, quando, devido a esse quadro, foi-lhe recomendada mudança do estilo de vida e prescrita farmacoterapia. Procura hoje a Unidade Básica de Saúde (UBS) com níveis tensionais elevados, glicemia alterada e referindo ter deixado de usar os medicamentos anti-hipertensivos prescritos dizendo “eles estão me fazendo sentir doente”. O paciente relata que, durante a pandemia da COVID-19, deixou de seguir as orientações alimentares, de atividade física e de cessação do tabagismo. Para esse caso, a conduta a ser adotada pela equipe da UBS é"},"A":{"antes_md5":"0dc70ee3441aebbc64de540b491ad9c0","depois":"construir um projeto terapêutico singular e pactuar com o paciente as propostas de ações para a mudança do estilo de vida e a adesão medicamentosa."},"B":{"antes_md5":"e9bc8fb1ab4217e91b813a4191db9b77","depois":"esclarecer o paciente, no projeto terapêutico singular, sobre as consequências da não adesão ao tratamento, destacando o perigo dos potenciais danos clínicos e reiterando firmemente o aconselhamento."},"C":{"antes_md5":"9b6d9d6ac675dc178321264c814d708d","depois":"utilizar, no projeto terapêutico singular, a negação do paciente aos problemas apresentados e a adesão ao tratamento como formas de pressão para obtenção da mudança do estilo de vida."},"D":{"antes_md5":"fe8331bf95cf4cd3017f0379401fe3a4","depois":"condicionar, na construção do projeto terapêutico singular, a adesão às mudança do estilo de vida e ao tratamento farmacológico e comunicar ao paciente que, se não seguir as orientações da equipe, não poderá mais ser atendido na UBS."}}},{"id":"revalida_2022_1_q006","code":"REV-2022.1-Q006","campos":{"A":{"antes_md5":"4ad4baa471c2361034f878fe5a1c6be1","depois":"clonidina, via oral, com o objetivo de reduzir a PA em até 50% em 24 horas ou para uma PA na faixa de 140 x 90-85 mmHg."},"B":{"antes_md5":"f2b4ec5aa8415f20507eb65e0ad8b34f","depois":"nitroprussiato endovenoso com o objetivo de reduzir a PA em até 25% em 2 horas ou para uma PA na faixa de 160 x 100-110 mmHg."},"C":{"antes_md5":"268e11db4b4c9678633ae5942adfcdb8","depois":"nitroglicerina endovenosa com o objetivo de reduzir a PA em até 25% em 2 horas ou para uma PA na faixa de 160 x 100-110 mmHg."},"D":{"antes_md5":"1292c8c58d2eb47d113f201e4882ae3c","depois":"captopril, via sublingual, com o objetivo de reduzir a PA em 50% em 8 horas ou para uma PA na faixa de 140 x 90-85 mmHg."}}},{"id":"revalida_2022_1_q007","code":"REV-2022.1-Q007","campos":{"A":{"antes_md5":"cf938426d2581f93a78edad79783bc08","depois":"Laparotomia com rafia da laceração hepática e drenagem do hematoma subcapsular."},"B":{"antes_md5":"ff3f172149f56fdd1ee84bd1d92b13ce","depois":"Laparotomia, hemostasia com compressas no fígado e reabordagem cirúrgica após 48 horas."},"C":{"antes_md5":"8d7e244de42bda158933245e3bf12a3a","depois":"Internação em Unidade de Terapia Intensiva com monitorização hemodinâmica e hematócrito seriado."}}},{"id":"revalida_2022_1_q008","code":"REV-2022.1-Q008","campos":{"A":{"antes_md5":"062f55e02fd2d0e9a3f7071a07de8955","depois":"Antiestreptolisina O e ecocardiograma."},"B":{"antes_md5":"6ebfeb76f7dd2ab4560a408b29c5c06c","depois":"Anticorpo antinuclear e fator reumatoide."},"C":{"antes_md5":"8b23dc98cff3fbbeec1dbdf74ff7949c","depois":"Ultrassonografia e punção articular de joelho."},"D":{"antes_md5":"bfe023345410d3159828a983639ab8aa","depois":"Hemograma e provas de atividade inflamatória."}}},{"id":"revalida_2022_1_q009","code":"REV-2022.1-Q009","campos":{"statement":{"antes_md5":"b4e8e0467fbed71412a1a68d347adf79","depois":"Uma paciente com 30 anos de idade, gestante pela 3ª vez, comparece ao centro de saúde para acompanhamento pré-natal. Relata que os outros dois partos foram normais, há 10 e 8 anos, que não houve nenhuma intercorrência nas outras gestações e que não tem nenhuma doença diagnosticada. Refere sintomas típicos de início de gestação: enjoo matinal e sonolência. Está com 13 semanas de gestação e apresenta os resultados dos exames de pré-natal anteriormente solicitados. Entre eles, o resultado da glicemia de jejum mostra 132 mg/dL. Com relação a esse caso, qual é a conduta adequada?"},"B":{"antes_md5":"2630eb77430895af179ab94daddd4ab3","depois":"Encaminhar a gestante para pré-natal de alto risco, já que se trata de diabetes mellitus prévio diagnosticado na gestação."},"C":{"antes_md5":"26b4bd715565f7fb4e146f6e883b37c8","depois":"Solicitar um teste de tolerância à glicose oral com 75 g imediatamente para elucidar o diagnóstico e avaliar necessidade de encaminhar a paciente ao ambulatório especializado."},"D":{"antes_md5":"715add5ff8040728d75e50312cd3d1ba","depois":"Solicitar um teste de tolerância à glicose oral com 75 g com 26 semanas para elucidar o diagnóstico e avaliar necessidade de encaminhar a paciente ao ambulatório especializado."}}},{"id":"revalida_2022_1_q010","code":"REV-2022.1-Q010","campos":{"statement":{"antes_md5":"51569e5cdbcdbf32cb1738eb0386afbe","depois":"Diante da pandemia da COVID-19, e segundo o guia de vigilância epidemiológica emergência de saúde pública de importância nacional pela doença pelo coronavírus 2019 – COVID-19 (2021), o Ministério da Saúde emitiu orientações de biossegurança durante a investigação de infecções respiratórias a partir de pacientes com suspeita de infecção por SARS-CoV-2. Nesta circunstância, para a coleta de material potencialmente gerador de aerossol, constitui a primeira linha de proteção destinada aos profissionais da saúde, os seguintes equipamentos de proteção individual (EPI):"},"A":{"antes_md5":"b6ce47cb6986d7c2a705299ded5165ae","depois":"gorro descartável, protetor facial, máscara PFF2 e avental de pano."},"B":{"antes_md5":"c9515636b0ec1bd15348afd09ef5c427","depois":"óculos de proteção, máscara cirúrgica e avental de mangas compridas."},"C":{"antes_md5":"927a4fd28a4ca25de6e63be2362080f3","depois":"gorro descartável, óculos de proteção ou protetor facial, máscara PFF2 (N95 ou equivalente), avental de mangas compridas, luva de procedimento e calçados fechados."},"D":{"antes_md5":"0b067b0269ff177ba96c92415d023f9b","depois":"gorro descartável, óculos de proteção ou protetor facial, máscara de pano/tecido (dupla camada), avental de mangas compridas, luva de procedimento e calçados fechados."}}},{"id":"revalida_2022_1_q011","code":"REV-2022.1-Q011","campos":{"statement":{"antes_md5":"6a98265dc8bdcee139a77262efa104ca","depois":"Uma paciente com 22 anos de idade dá entrada na unidade de emergência de hospital de média complexidade com quadro de asma descompensada. A paciente, que se apresenta taquicárdica (frequência cardíaca: 110 batimentos por minuto), taquipneica (frequência respiratória: 28 incursões respiratórias por minuto) e febril (38,3 °C), relata descompensação do quadro respiratório há 2 dias, tendo utilizado medicação de resgate (beta 2 agonista adrenérgico inalatório) por diversas vezes ao longo desse período, sem obter melhora. Diagnosticada com asma ainda na infância, ela conta que sua doença vem sendo classificada como asma moderada persistente, estando em uso regular de beta 2 agonista de longa duração (salmoterol) e corticoide inalatório (budesonida) em baixa dose, além da medicação de resgate. Ao exame físico, nota-se também leve cianose e sibilância inspiratória e expiratória; a hemodinâmica encontra-se estável bem como o nível de consciência. A paciente é submetida a administração de nebulização com beta 2 agonista adrenérgico inalatório e anticolinérgico de ação rápida (brometo de ipratrópio). A despeito da oxigenioterapia sob máscara nasal com reservatório, repetição da nebulização e da administração de metilprednisolona intravenosa, a paciente continua com algum grau de desconforto respiratório. Exames laboratoriais indicam a presença de possível processo infeccioso bacteriano (leucocitose com leve desvio à esquerda e aumento da proteína C reativa [PCR]), confirmado na radiografia de tórax, que indica padrão de condensação segmentar no lobo inferior direito. A gasometria arterial revelou o seguinte padrão: pH: 7,44 (valor de referência [VR]: 7,35-7,45); PaO₂: 65 (VR para idade: 95); PaCO₂: 44 (VR: 35-45); HCO₃⁻: 22 (VR: 24 +/- 2); SaO₂: 91% (VR > 94%). Completada essa avaliação inicial, o médico opta por indicar a realização de intubação orotraqueal preventiva. A principal razão para a tomada dessa decisão"},"A":{"antes_md5":"00a1f6c16979bf3680f09c0c23446bea","depois":"foi o nível reduzido da PaO₂ à gasometria arterial."},"B":{"antes_md5":"bea4e409eba3f6a29d4f9e1b362fcf6f","depois":"foi o nível normal da PaCO₂ à gasometria arterial."},"D":{"antes_md5":"dafba1d17bd18a20685cea301f5c3f58","depois":"foi a presença de sibilância inspiratória e expiratória associada à taquipneia."}}},{"id":"revalida_2022_1_q012","code":"REV-2022.1-Q012","campos":{"A":{"antes_md5":"47750eabf7b73b9d634c62d3ef8ad3ba","depois":"Colecistite aguda; antibioticoterapia venosa."},"B":{"antes_md5":"d6e8ccb425945b2fe5c11f70485eed1c","depois":"Colangite aguda; antibioticoterapia venosa."},"C":{"antes_md5":"f4b0a5b64ef13f64039bf173ecda7e03","depois":"Colecistite aguda; colecistectomia de emergência."},"D":{"antes_md5":"69b31a70bd5bc261d5fc3f732cd31355","depois":"Colangite aguda; drenagem cirúrgica das vias biliares."}}},{"id":"revalida_2022_1_q013","code":"REV-2022.1-Q013","campos":{"A":{"antes_md5":"d732072ed4e1cc6f4c58d3a44293afe7","depois":"tríplice viral aos 12 meses e uma dose da vacina tetraviral aos 15 meses."},"D":{"antes_md5":"8f5b00db16a33882c87fd5d63003b50f","depois":"antissarampo aos 18 meses e outra dose da vacina tetraviral aos 18 meses."}}},{"id":"revalida_2022_1_q014","code":"REV-2022.1-Q014","campos":{"A":{"antes_md5":"f8f6e866d03e80672f8629fa6708169f","depois":"acesso venoso e decúbito lateral esquerdo, além de encaminhar a paciente para cesariana de urgência."},"B":{"antes_md5":"5d66b6d9b1b51bf4d1ba080514e718e9","depois":"decúbito lateral esquerdo e exames laboratoriais, além de reavaliar a pressão arterial da paciente e proceder a resolução da gestação."},"C":{"antes_md5":"43103d6798b3f95027e8797c4915e324","depois":"acesso venoso e exames laboratoriais, além de iniciar sulfato de magnésio e proceder a resolução da gestação."},"D":{"antes_md5":"b2dc86cb424fdf873326c3255f7a085b","depois":"acesso venoso e exames laboratoriais, além de encaminhar a paciente para cirurgia devido a cesariana anterior."}}},{"id":"revalida_2022_1_q015","code":"REV-2022.1-Q015","campos":{"A":{"antes_md5":"f4e742cdb7d84c0179fec4cfad1911da","depois":"Diabetes mellitus gestacional não detectado; manter seguimento na rotina de pré-natal de risco habitual na USF."},"B":{"antes_md5":"db4fba490a76ea56e069ea2ed843b8e7","depois":"Diabetes mellitus gestacional; solicitar início, na USF, da insulinoterapia (2,5 UI/Kg/dia) e avaliar glicemia capilar em 15 dias."}}},{"id":"revalida_2022_1_q016","code":"REV-2022.1-Q016","campos":{"A":{"antes_md5":"f25009b8f43cf44dc77505e6716ad29b","depois":"leptospirose."},"B":{"antes_md5":"43976d9eac92ccfc725944e3b5799677","depois":"mononucleose."},"C":{"antes_md5":"712dcf3ec2a025164cc5f97431924692","depois":"colecistite aguda."},"D":{"antes_md5":"76fc960711897aafe67d670ba610e34e","depois":"hepatite aguda viral."}}},{"id":"revalida_2022_1_q017","code":"REV-2022.1-Q017","campos":{"statement":{"antes_md5":"dfea0026305d8fdc8ec499450190cb68","depois":"Um homem com 33 anos de idade chega para atendimento no Pronto-Socorro de hospital de nível secundário. Relata vômitos com sangue assim como fezes escurecidas e fétidas há 1 dia. Ao exame físico, encontra-se descorado, taquicárdico, hipotenso. Realizou endoscopia digestiva alta que evidenciou úlcera péptica pré-pilórica (tipo III de Johnson), com sangramento em jato proveniente da lesão (Classificação Ia de Forrest), sendo realizada hemostasia da ulceração com solução de adrenalina. Doze horas após a terapêutica endoscópica, apresentou novamente vômitos com sangue em grande quantidade, frequência cardíaca de 110 batimentos por minuto e pressão arterial de 80 x 40 mmHg. Com base na história clínica do paciente e nos dados do exame físico, o tratamento adequado deve ser"},"B":{"antes_md5":"52d67b29cbac32deee8941d7e5a4d965","depois":"terapia intensiva, inibidor de bomba de prótons e tratamento operatório."}}},{"id":"revalida_2022_1_q018","code":"REV-2022.1-Q018","campos":{"statement":{"antes_md5":"30a60c8d2aa016832ef595166052f91f","depois":"Um médico de plantão em uma unidade de saúde materno-infantil de hospital secundário recebe a informação de parto de uma gestante com antecedente de tratamento de sífilis primária no segundo trimestre da gestação, com penicilina benzatina 2.4000.000 UI, dose única, via intramuscular. O parto foi normal, sem intercorrências, com recém-nascido (RN) a termo, capurro de 39 semanas e 4 dias, peso: 3.450 g, estatura: 49 cm e apgar: 9-10; ele está assintomático e com exame físico sem alterações. Houve a coleta de sorologias da mãe e do RN. Os resultados do VDRL mostram títulos maternos de 1:4 e títulos do RN de 1:32. Em relação ao recém-nascido, a conduta a ser adotada é"},"A":{"antes_md5":"4b57c25c3e8c873e245b29e625f24e5e","depois":"fazer seguimento ambulatorial com novas coletas de VRDL nas consultas de rotina."},"B":{"antes_md5":"8bf6213066b6cec383ccada2a2b2d00a","depois":"solicitar radiografia de ossos longos e hemograma e notificar sífilis congênita se exames alterados."},"C":{"antes_md5":"f6e86ca34303a3f6427b1609a52f71b3","depois":"notificar sífilis congênita, solicitar líquor, radiografia de ossos longos, hemograma e iniciar tratamento."},"D":{"antes_md5":"c1b3115bd888ef3c965264b1cbaa5412","depois":"notificar sífilis congênita e iniciar tratamento com penicilina cristalina endovenosa por 10 dias."}}},{"id":"revalida_2022_1_q019","code":"REV-2022.1-Q019","campos":{"A":{"antes_md5":"44cb719d5eeaec1881d1cdfd8ca52ef7","depois":"Apendicite aguda; cirurgia."},"B":{"antes_md5":"c961505b4fd742fa11525d6d79f5a39f","depois":"Gestação ectópica rota; cirurgia."},"C":{"antes_md5":"6c3a17d0389da01011aaa2ae3d53580b","depois":"Doença inflamatória pélvica; antibioticoterapia parenteral."},"D":{"antes_md5":"23aafb48a70206cc7c4c7a81b246cdb6","depois":"Aborto ou ameaça de aborto; internação para observação."}}},{"id":"revalida_2022_1_q020","code":"REV-2022.1-Q020","campos":{"A":{"antes_md5":"1724fa384faab6917e3f0bdcf024b96b","depois":"não há espaço para a participação do controle social no desenvolvimento do projeto de intervenção."},"B":{"antes_md5":"71069aa2a5113be59ca8ecce6c5bde89","depois":"a participação do controle social é legalmente permitida e muito importante para o desenvolvimento do projeto."},"C":{"antes_md5":"55a625a6bb6445ccc77eb684fcb29b68","depois":"a participação do controle social no desenvolvimento do projeto seria importante, mas não é permitida pela legislação brasileira."},"D":{"antes_md5":"cec046b16660bdb86fc5315ea4ea11c1","depois":"a participação do controle social no desenvolvimento do projeto só é permitida após aprovação pelo poder legislativo do município."}}},{"id":"revalida_2022_1_q021","code":"REV-2022.1-Q021","campos":{"statement":{"antes_md5":"da0461c751e2e76b99606d5d81ae34b8","depois":"Uma jovem com 14 anos de idade procura atendimento em Unidade Básica de Saúde (UBS) devido a crises recorrentes de lombalgia há, pelo menos, 4 anos. Relata que a dor é intensa, de início agudo, sem fator desencadeante que tenha identificado e que já havia precisado ser levada a pronto atendimento em algumas dessas crises para administração de analgésicos endovenosos. Conta que, em algumas dessas ocasiões, realizou exames laboratoriais, informando que apenas era detectada a presença de anemia. Acrescenta que, no último atendimento, também foi realizada uma radiografia da coluna lombar, que evidenciou a presença de vértebras em “H”, tendo sido orientada a procurar o médico da UBS para prosseguimento de investigação. Diante desse histórico, o médico da UBS deve considerar a hipótese de"},"A":{"antes_md5":"47645ff5f2f9a08fe05ed289acac0adf","depois":"hiperparatireoidismo e solicitar dosagem de paratormônio."},"B":{"antes_md5":"4ec8fcc8b81e87487e76c4ec6ab30945","depois":"anemia falciforme e solicitar eletroforese de hemoglobina."},"C":{"antes_md5":"89169966943ad97761c4792678c42b39","depois":"fraturas vertebrais secundárias e solicitar tomografia computadorizada."},"D":{"antes_md5":"15833571b1e686b3ea9f3f8beafbca59","depois":"espondilite anquilosante e solicitar ressonância magnética de sacroilíacas."}}},{"id":"revalida_2022_1_q022","code":"REV-2022.1-Q022","campos":{"A":{"antes_md5":"8b61d15f5a2b986b540324b49d2fb523","depois":"radiografia do tórax e toracocentese no segundo espaço intercostal direito."},"C":{"antes_md5":"438393698637449cedabe1870598477d","depois":"toracocentese inicialmente e drenagem pleural fechada no quarto espaço intercostal direito."}}},{"id":"revalida_2022_1_q023","code":"REV-2022.1-Q023","campos":{"statement":{"antes_md5":"b8bb4519c99cd8d58ea8b447e5125f40","depois":"Um lactente com 18 meses de idade é atendido em Unidade Básica de Saúde em virtude de a mãe ter notado “algo duro” na barriga do filho durante o banho há 1 semana. A mãe fez uso de laxativo por 2 dias, mas não houve desaparecimento da tumoração. Nesse período, ela notou que a criança estava mais apática e inapetente. Ela nega sintomas respiratórios e febre. Relata que o filho nasceu de parto cesárea a termo, sem intercorrências neonatais e que recebeu aleitamento materno exclusivo por 6 meses. Observa-se bom ganho pondero-estatural e vacinação em dia. A mãe traz exame de urina realizado há 3 dias, que mostra hematúria. Ao exame físico, apresenta regular estado geral, apático, hipoativo, descorado 1+/4+, afebril, acianótico, frequência cardíaca de 104 batimentos por minuto, frequência respiratória de 32 incursões respiratórias por minuto, pressão arterial no percentil 95 para a idade e estatura. Ausência de linfoadenomegalias. Abdome com presença de massa de consistência endurecida no andar superior, sem ultrapassar linha média. Membros sem edema ou lesões. Considerando esse caso clínico, a principal hipótese diagnóstica e o exame indicado para elucidar o diagnóstico são, respectivamente,"},"A":{"antes_md5":"1af43280ce6f4cfde806f6db88203058","depois":"linfoma; ultrassonografia de abome."},"B":{"antes_md5":"3ce0691581533d2e350040f370d4125d","depois":"tumor de Wilms; ultrassonografia de abdome."},"C":{"antes_md5":"b6f5868ab7462dd9b2b0337eeeda9bb3","depois":"glomerulonefrite difusa aguda; complemento sérico."}}},{"id":"revalida_2022_1_q024","code":"REV-2022.1-Q024","campos":{"A":{"antes_md5":"ec6becc6ebc3ea5f8ba41a7df4c4cc7a","depois":"solicitar dosagens hormonais e fazer o encaminhamento da paciente para centro de referência."},"B":{"antes_md5":"becf2f246a717500859d959aec273141","depois":"pedir avaliação ultrassonográfica da presença e tamanho de útero e ovários da paciente."},"C":{"antes_md5":"1f04f1c3fb0e1a88ac940594fb0dbcc2","depois":"solicitar teste de progesterona via oral da paciente para estímulo endometrial."},"D":{"antes_md5":"f5f12a52d2d9fdf7a0e59971d570a770","depois":"orientar e esclarecer a paciente sobre a normalidade do desenvolvimento."}}},{"id":"revalida_2022_1_q025","code":"REV-2022.1-Q025","campos":{"A":{"antes_md5":"e98086b18b9aea65b2001abf429b3892","depois":"homogeneizar as orientações para toda a comunidade, já que a COVID-19 atinge de modo semelhante todos os grupos populacionais."},"B":{"antes_md5":"c6a179da4e7dd1f95b127ef43a980dec","depois":"assumir um papel de vigilância em saúde, com prioridade às necessidades dos grupos mais vulneráveis em relação à pandemia da COVID-19."},"C":{"antes_md5":"bfe5bf495f8a83c237a9b444f3fc6ddb","depois":"buscar orientações dos órgãos competentes, alertando contra quaisquer recomendações de curadores tradicionais referentes à pandemia da COVID-19."},"D":{"antes_md5":"a75c40f08cf07446c084b3a88f2e1501","depois":"posicionar-se com neutralidade diante das necessidades da comunidade e das diferentes orientações das autoridades municipal, estadual e federal no combate à COVID-19."}}},{"id":"revalida_2022_1_q026","code":"REV-2022.1-Q026","campos":{"statement":{"antes_md5":"6f9bc9e1e3db6a46950e6493ca486de3","depois":"Um homem com 48 anos de idade, tabagista, em tratamento irregular de hipertensão arterial sistêmica, diabetes mellitus e dislipidemia, é admitido na unidade de emergência de hospital de pequeno município do interior, com quadro de dor torácica de forte intensidade, tipicamente anginosa, associada a diaforese, náuseas e vômitos. Segundo informa, o quadro álgico tem cerca de 4 horas de evolução, não tendo procurado antes a unidade de saúde por receio de contaminação devido à pandemia em curso. O exame físico dirigido revela um paciente em moderado desconforto agudo, ansioso, com pressão arterial (PA) de 102 x 70 mmHg, frequência cardíaca de 102 batimentos por minuto, levemente taquipneico, frequência respiratória de 22 incursões respiratórias por minuto. Na ausculta cardíaca, revelam-se uma 4ª bulha e um sopro sistólico suave na ponta, estando os pulmões limpos. É realizado, então, um eletrocardiograma (ECG) nos primeiros 10 minutos de atendimento, que mostra a presença de um supradesnível do segmento ST superior a 2 mm nas derivações D2, D3, aVF e V1, além de infradesnível de ST de 3 mm nas derivações V2 a V4, nas quais são observadas ondas R aumentadas e ondas T positivas proeminentes. São administrados nitrato sublingual e ácido acetilsalicílico (AAS), além de ser solicitada a infusão de tenecteplase intravenosa em bolus, uma vez que não há serviço de hemodinâmica na região. Enquanto é providenciada a elaboração do trombolítico, o paciente refere piora dos sintomas, sendo verificado que ele se encontra ainda mais pálido e hipotenso (PA: 80 x 46 mmHg), a despeito de sua ausculta pulmonar manter-se sem ruídos adventícios. Considerando os dados relatados, a melhor explicação para a piora clínica do paciente logo após a instituição da abordagem inicial é"},"A":{"antes_md5":"02a9e4131704002e9c2e6acc1e11af4e","depois":"agravamento da hipercalemia pelo AAS."},"B":{"antes_md5":"a523c393518f83537c986db6387b79c6","depois":"desenvolvimento de rotura de septo interventricular."},"C":{"antes_md5":"40d68d074d0d0dd767c0bb17f754dd3e","depois":"medicação inadequada na coexistência de infarto de ventrículo direito."},"D":{"antes_md5":"0b73b02160af2acdb7ab8d100f0f67bc","depois":"instalação de choque cardiogênico por grave disfunção ventricular esquerda."}}},{"id":"revalida_2022_1_q027","code":"REV-2022.1-Q027","campos":{"statement":{"antes_md5":"d49f6c78086b1a706cf15a3fbcbec29a","depois":"Um homem com 23 anos de idade, em atendimento no Pronto-Socorro de hospital de nível terciário, apresenta trauma abdominal contuso após acidente automobilístico, sem evidências de lesões em outros segmentos corpóreos. Ao exame físico, apresenta frequência cardíaca de 84 batimentos por minuto, preenchimento capilar menor que 2 segundos, pressão arterial de 115 x 65 mmHg. Durante o atendimento inicial foi utilizada sondagem vesical de demora que evidenciou hematúria maciça. A tomografia de abdome com contraste endovenoso mostrou uma lesão renal grau III, correspondendo a laceração cortical do parênquima renal maior que 1 cm, sem extravasamento urinário. Não foram evidenciadas outras lesões no abdome. Considerando essa história clínica, os dados do exame físico e da tomografia, a conduta correta é indicar"},"A":{"antes_md5":"071f51da31d53a95600e781fb4dc49b4","depois":"arteriografia e embolização para coibir o sangramento."},"B":{"antes_md5":"c03887f1980566deb9d2a39f7726c220","depois":"tratamento operatório em função da hematúria maciça."},"C":{"antes_md5":"d1bdfe6e9d43b338f9ba82192926f84f","depois":"sonda vesical de três vias e irrigação com solução salina 0,9%."}}},{"id":"revalida_2022_1_q028","code":"REV-2022.1-Q028","campos":{"A":{"antes_md5":"4d320ffce2fc03271f2503e9f2a40310","depois":"Peso baixo para a idade."},"B":{"antes_md5":"71e1ef9763f6e47391e6e6bc0340adfd","depois":"Peso elevado para a idade."},"C":{"antes_md5":"c3aa9dd2944fe90f49fe89e671b9df64","depois":"Peso adequado para a idade."},"D":{"antes_md5":"96699aed7101fe7b96e469f2fde80142","depois":"Peso muito baixo para a idade."}}},{"id":"revalida_2022_1_q029","code":"REV-2022.1-Q029","campos":{"A":{"antes_md5":"adc3c5f7c0fab360ff2cff241394d208","depois":"Sífilis (lesão secundária); deve ser solicitado VDRL e teste treponêmico com urgência para definir conduta."},"B":{"antes_md5":"3d2a73123a4ae4640a62b9054da92835","depois":"Sífilis (lesão primária); indicação de tratamento com penicilina benzatina para a mulher e o(s) parceiro(s)."},"C":{"antes_md5":"3d25a3659767311c6e04cc3f4618866f","depois":"Herpes Genital; deve ser solicitada sorologia (IGG e IGM) e cultura de secreção da lesão e, após coleta, iniciar tratamento com aciclovir."},"D":{"antes_md5":"0ef7e4327e4610d078dbd8a771e54b30","depois":"Herpes Genital; indicação de tratamento com aciclovir e com 36 semanas de gestação deve ser prescrito aciclovir profilático, para diminuir o risco de lesões ativas no momento do parto."}}},{"id":"revalida_2022_1_q030","code":"REV-2022.1-Q030","campos":{"A":{"antes_md5":"629dd7edb26a028f14f38b28524038b9","depois":"mensalmente até a 34ª semana."},"B":{"antes_md5":"f29f8cafdd289a153577526ed3fd1350","depois":"mensalmente até a 28ª semana."},"C":{"antes_md5":"b519b95f91f8732eb198a5170e6323d4","depois":"quinzenalmente até a 34ª semana."},"D":{"antes_md5":"8c4c8aa154b2918feaf4805e98435f8e","depois":"quinzenalmente até a 28ª semana."}}},{"id":"revalida_2022_1_q031","code":"REV-2022.1-Q031","campos":{"A":{"antes_md5":"e8dd4f71bfaf92a80262defa9661e485","depois":"encaminhar o paciente a um centro especializado de trauma."},"B":{"antes_md5":"664c7d44ea66db128fb0ad7d7e7fe658","depois":"iniciar tratamento do paciente com antibiótico conforme o antibiograma."},"C":{"antes_md5":"a41fd8fe31433e0175dd69b03d7c6b6e","depois":"observar o quadro clínico do paciente e instituir precaução de contato."}}},{"id":"revalida_2022_1_q032","code":"REV-2022.1-Q032","campos":{"A":{"antes_md5":"3a98b12a1458ccc30f1cddb90c755e5b","depois":"Mepivacaína e lidocaína."},"B":{"antes_md5":"961b0f019cce4037dbbcc1f499dcab6f","depois":"Lidocaína e bupivacaína."},"C":{"antes_md5":"622db2c8f32e8fcd572b7c5d1b666a1f","depois":"Cloroprocaína e lidocaína."},"D":{"antes_md5":"8cd779c014cce198c985c61f74ffb41a","depois":"Cloroprocaína e mepivacaína."}}},{"id":"revalida_2022_1_q033","code":"REV-2022.1-Q033","campos":{"A":{"antes_md5":"286ecb4d75f1be7a3bc8378d0d17677a","depois":"Penicilina intravenosa."},"B":{"antes_md5":"71ed1944c4910726d9fffbee7d197a98","depois":"Gentamicina intravenosa."},"C":{"antes_md5":"47e0a23126b1fb80170158ffb0e94d1e","depois":"Ceftazidima intravenosa."},"D":{"antes_md5":"fa0b9ab32d0f215802ff8be0f7d6ce4a","depois":"Vancomicina intravenosa."}}},{"id":"revalida_2022_1_q034","code":"REV-2022.1-Q034","campos":{"A":{"antes_md5":"a91d8b18a3879e0207fc22485d50df69","depois":"As características ultrassonográficas são de alto risco para malignidade."},"B":{"antes_md5":"15e00501b74094c7c34a3f5ef787255a","depois":"As características ultrassonográficas correspondem a processos não neoplásicos ou fisiológicos."},"C":{"antes_md5":"fbe0addcb2eea0afdad4bbd90352ef4a","depois":"As características ultrassonográficas são inespecíficas para classificar risco de malignidade."},"D":{"antes_md5":"4a442b1d4f9891dd2584b9916e025e3b","depois":"O exame de ultrassom não é adequado para a avaliação das características da massa anexial."}}},{"id":"revalida_2022_1_q035","code":"REV-2022.1-Q035","campos":{"A":{"antes_md5":"f75e5ea69a5a9bea67b048ba48d15b64","depois":"Hemograma; tipagem sanguínea e fator Rh; glicemia de jejum; testes de rastreamento para sífilis, HIV e citomegalovírus; exame de urina e urocultura."},"C":{"antes_md5":"226903fe0fcc572c453e843697e7fb64","depois":"Hemograma; tipagem sanguínea e fator Rh; glicemia de jejum; testes de rastreamento para sífilis, HIV, toxoplasmose e hepatite B; exame de urina e urocultura."},"D":{"antes_md5":"e13eb59fc85928a5137f3ebb225c231c","depois":"Hemograma; tipagem sanguínea e fator Rh; glicemia de jejum; testes de rastreamento para sífilis, HIV, citomegalovírus e hepatite B e C; exame de urina e urocultura."}}},{"id":"revalida_2022_1_q036","code":"REV-2022.1-Q036","campos":{"A":{"antes_md5":"d513ba5399f9aa3ce4093b7373556279","depois":"deficiência de vitamina B12."},"B":{"antes_md5":"c29a60180f328dea5746356db48ce6b1","depois":"aplasia de medula óssea."},"C":{"antes_md5":"8b8fabab2c438aef3917e67a6a894ac6","depois":"deficiência de G6PD."},"D":{"antes_md5":"5d3fc5765fd1f85a7136ab3b11688b39","depois":"hipotireoidismo."}}},{"id":"revalida_2022_1_q037","code":"REV-2022.1-Q037","campos":{"A":{"antes_md5":"87b5c75d4a7907f00134d6f627d60b17","depois":"fasciotomia, reposição hídrica por via oral, radiografia de membro superior direito e observação no PS."},"B":{"antes_md5":"01c106d89dbe26347cb675b5f333627a","depois":"sondagem vesical, pesquisa de mioglobina na urina, analgesia, monitorização eletrocardiográfica e internação hospitalar."},"C":{"antes_md5":"553e54fe094ee767b576e376e8111894","depois":"avaliação do cirurgião plástico, considerando que a superfície corpórea queimada corresponde a 9%, além de reposição hídrica por via oral."},"D":{"antes_md5":"6f779c3f213fc63c70f475d636dff735","depois":"reposição com fluidos endovenosos, monitorização eletrocardiográfica e transferência para centro especializado em queimados, após estabilização."}}},{"id":"revalida_2022_1_q038","code":"REV-2022.1-Q038","campos":{"A":{"antes_md5":"11aad2aa6c4c33ea2786bec22a887124","depois":"Tiopental; arritmia cardíaca."},"B":{"antes_md5":"447cd7b668edbcafa95119cdbf6d94e1","depois":"Midazolan; hipertensão intracraniana."},"C":{"antes_md5":"aead7067aabb13be9375efd3976e7ff8","depois":"Propofol; instabilidade hemodinâmica."},"D":{"antes_md5":"867c03e1b6492bbb0d2c2e4249a11aa5","depois":"Fenobarbital sódico; depressão respiratória."}}},{"id":"revalida_2022_1_q039","code":"REV-2022.1-Q039","campos":{"statement":{"antes_md5":"313e8f47e7096e8854f4988be3d20e7b","depois":"Uma paciente com 25 anos de idade, casada há 3 meses, usa Dispositivo Intrauterino (DIU) como método anticoncepcional. Procura consulta em centro de saúde com queixa de corrimento vaginal abundante. Refere que a secreção é amarelada, que sente ardor e dor, que piora na relação sexual. Ao exame ginecológico, é observada hiperemia de genitais externos e de parede vaginal, com presença de secreção amarelo-esverdeada com pequenas bolhas, não aderida à parede vaginal, além de colo uterino com colpite e “aspecto de morango”. Nesse caso, o exame a ser realizado e seu resultado mais provável são, respectivamente,"},"A":{"antes_md5":"66b6d4e85466ee60d1ef9722ac4e7473","depois":"exame de secreção vaginal com coloração de Gram; observadas “Clue Cells”."},"D":{"antes_md5":"bff6a6c3a694fd9fe6810848b42fcfba","depois":"exame a fresco de secreção vaginal com hidróxido de potássio; observadas pseudo-hifas e esporos."}}},{"id":"revalida_2022_1_q040","code":"REV-2022.1-Q040","campos":{"A":{"antes_md5":"918646e4b9ef38bf961242a5b032ee14","depois":"Acidentes ofídicos."},"B":{"antes_md5":"d99444366b6d7c8db1e7b7aa3427622a","depois":"Acidentes com arraia."},"C":{"antes_md5":"e870b3594f199d148de983e167ebcc55","depois":"Acidentes escorpiônicos."},"D":{"antes_md5":"1fec3fec0330863088d125aacdd823be","depois":"Intoxicação por mercúrio."}}},{"id":"revalida_2022_1_q041","code":"REV-2022.1-Q041","campos":{"A":{"antes_md5":"943dc4951f18a1a9f216bd7e5d21bb85","depois":"a terapia com iodo radioativo."},"B":{"antes_md5":"bfd2c4750a174d95b8148605164279b6","depois":"o uso de metimazol via oral."},"C":{"antes_md5":"d8122022702ffd024aa4d3b610bdb41c","depois":"a tireoidectomia subtotal."},"D":{"antes_md5":"224f695fdb4c37dfa0fa3541e9a558b2","depois":"a tireoidectomia total."}}},{"id":"revalida_2022_1_q042","code":"REV-2022.1-Q042","campos":{"statement":{"antes_md5":"0e8eb99bdaf99520a64880cc5fb9c61b","depois":"No ambulatório de um hospital secundário, o médico de plantão recebe uma paciente de 43 anos de idade que se encontra no 10º dia de pós-operatório de uma histerectomia total abdominal por doença benigna. A paciente queixa-se de mal-estar, hiporexia e febre (37,3 °C) há cerca de 2 dias. Ao exame físico, a incisão operatória encontra-se um pouco hiperemiada e quente. A semiologia pulmonar é normal; não há queixa de disúria nem sinais de flebite. Considerando esse caso, assinale a opção que apresenta, respectivamente, a classificação da cirurgia quanto ao grau de contaminação e qual deveria ter sido a melhor conduta pré-operatória para evitar a infecção pós-operatória."},"A":{"antes_md5":"ef6226e747e95e66213118b24e9f1f81","depois":"Contaminada; realizar antibioticoprofilaxia com a administração de cefazolina 1G IV durante o ato cirúrgico."},"B":{"antes_md5":"1026113a6b84939b1a716140134938ec","depois":"Contaminada; realizar antibioticoprofilaxia com a administração de cefazolina 2G IV uma hora antes do ato cirúrgico."},"C":{"antes_md5":"7e50d396a54542bcb3d20e8184eaf400","depois":"Limpa-contaminada; realizar antibioticoprofilaxia com a administração de cefazolina 1G IV durante o ato cirúrgico."},"D":{"antes_md5":"7cdd8e9f8659e643f53919ea4df3c33e","depois":"Limpa-contaminada; realizar antibioticoprofilaxia com a administração de cefazolina 2G IV uma hora antes do ato cirúrgico."}}},{"id":"revalida_2022_1_q043","code":"REV-2022.1-Q043","campos":{"A":{"antes_md5":"9848d5465116da45e9b909a79849d1b4","depois":"asma intermitente; tratar os episódios de exacerbação com inalação de beta 2 agonista de curta duração."},"B":{"antes_md5":"717a1f7caee9907cf57316791b52b6d2","depois":"asma persistente moderada não controlada; fazer uso de corticoide inalatório oral em dose moderada."},"D":{"antes_md5":"1e76ebaaaec2fb0a5bc0303626ae482e","depois":"asma persistente grave parcialmente controlada; iniciar corticoide inalatório oral em dosagem alta."}}},{"id":"revalida_2022_1_q044","code":"REV-2022.1-Q044","campos":{"A":{"antes_md5":"9a5839ceb62f1577d30622170dd1d14d","depois":"usar fármacos que reduzam o sangramento na fase dos sangramentos intermenstruais, por exemplo, anti-inflamatórios e/ou antifibrinolíticos."},"B":{"antes_md5":"e81bf5f94b4f9f6a7a09e48ee49b36a1","depois":"voltar a fazer uso de CHO de dose maior, podendo ser o mesmo que usava antes (etinilestradiol 35 mcg em associação com acetato de ciproterona 2 mg)."},"C":{"antes_md5":"a4329e810684a649697c7289907677cd","depois":"inserir o Dispositivo Intrauterino (DIU), pois existe contraindicação ao uso de métodos hormonais estroprogestativos por via oral."},"D":{"antes_md5":"718f27314ae00e27a4788be8537e20f5","depois":"usar outro CHO com o progestógeno acetato de ciproterona, pois o gestodeno frequentemente se associa com maior risco de sangramentos intermenstruais."}}},{"id":"revalida_2022_1_q045","code":"REV-2022.1-Q045","campos":{"statement":{"antes_md5":"7368ee93b81265009f99324f2e5b3d2b","depois":"Um paciente com 48 anos de idade busca atendimento em Unidade de Saúde da Família devido a quadro de tosse produtiva há cerca de 2 meses, associada a perda de peso e sudorese noturna. Paciente refere ter voltado a morar com os pais há 1 semana, depois de ter ficado em situação de rua nos últimos 3 anos, devido a um episódio de conflito familiar. Refere ter procurado o pronto atendimento há 1 mês, quando foi prescrita amoxicilina 500 mg, de 8 em 8 horas por 10 dias, porém sem melhora do quadro. O médico de família solicita, então, realização do teste rápido molecular para tuberculose, cujo resultado foi positivo, sendo negativa a resistência à rifampicina. Nesse caso, a conduta a ser adotada para o paciente é"},"A":{"antes_md5":"a4dfbd700ab39cec280d74d50359c4b7","depois":"solicitar cultura de escarro e aguardar o resultado para iniciar o tratamento de acordo com o teste de sensibilidade."},"C":{"antes_md5":"b5366373f7d785ee4f430a0aa4401b74","depois":"iniciar esquema básico com rifampicina, isoniazida, pirazinamida e etambutol, não havendo necessidade de coleta de cultura de escarro."},"D":{"antes_md5":"ba7fb5aa55261e635e5b9eb7fdc44e78","depois":"iniciar esquema básico com rifampicina, isoniazida, pirazinamida e etambutol, e reavaliar o caso após resultado da cultura de escarro e do teste de sensibilidade."}}},{"id":"revalida_2022_1_q046","code":"REV-2022.1-Q046","campos":{"statement":{"antes_md5":"d95529fb4a20f8648b285272d84087fc","depois":"Uma paciente com 30 anos de idade, sem comorbidades, compareceu à Unidade Básica de Saúde com queixas de disúria, tenesmo vesical, polaciúria e ardência miccional há 2 dias. Relatou vida sexual ativa, uso de método anticoncepcional e última menstruação na semana anterior ao surgimento dos sintomas. Negou quadro de infecção urinária no último ano ou história sugestiva de anormalidades do trato urinário. Diante desses dados, a principal hipótese diagnóstica é"},"B":{"antes_md5":"09f21f95d301b2691910c09ff831e3e7","depois":"sepse de foco urinário."},"C":{"antes_md5":"f1257113dca5aeb58c4666cd2d230ae8","depois":"bacteriúria assintomática."},"D":{"antes_md5":"f6591f94f6bbe5ea1b8f3ba4ff9d1912","depois":"infecção de trato urinário não complicada."}}},{"id":"revalida_2022_1_q047","code":"REV-2022.1-Q047","campos":{"statement":{"antes_md5":"da461feb58872d89282ea0b407869a29","depois":"Um paciente com 25 anos de idade, soldador, procurou Unidade de Pronto Atendimento relatando que, durante seu ofício, retirou o protetor facial momentaneamente e foi atingido por “flash” ocasionado pelo equipamento de solda no olho direito. O médico clínico socorrista evidenciou apenas eritema conjuntival. O paciente refere, nesse momento, irritabilidade e “sensação de areia” nos olhos, sem perda da acuidade visual. Nesse caso, a melhor medida a ser adotada pelo médico socorrista antes de encaminhar o paciente para avaliação especializada é"},"A":{"antes_md5":"8b96916e6e0053416b6531a9471c5080","depois":"curativo oclusivo e compressivo."},"B":{"antes_md5":"954dc5dc326cd3873cf172ec5fd15aca","depois":"oftalmoscopia e retirada de corpo estranho com pinça."},"C":{"antes_md5":"515e6832337ac1c8b5f41f8338c5e894","depois":"aplicação de colírio contendo antimicrobianos e corticoesteroides."},"D":{"antes_md5":"46be02aa20913e39004fb31f30538b7b","depois":"irrigação ocular com soro fisiológico a 0,9% em temperatura ambiente."}}},{"id":"revalida_2022_1_q048","code":"REV-2022.1-Q048","campos":{"A":{"antes_md5":"2b36d0fa17e40a559522be87b8929ee4","depois":"dengue grave com choque."},"B":{"antes_md5":"fc3179612f5d164e4fc68874b19ed765","depois":"síndrome do choque tóxico estafilocócico."},"D":{"antes_md5":"8aee5cbe6f85943837c68b210f9e016e","depois":"síndrome inflamatória multissistêmica pediátrica."}}},{"id":"revalida_2022_1_q049","code":"REV-2022.1-Q049","campos":{"statement":{"antes_md5":"6caee4bee1726f9a82f22e784ba7ea79","depois":"Uma paciente com 19 anos de idade, solteira, busca orientação médica em Unidade Básica de Saúde. Relata que teve duas gestações anteriores, sendo um parto a termo e um aborto, e que tem um filho vivo e saudável de 3 anos de idade. Informa que contraiu infecção pelo HIV há 2 anos e utiliza terapia antirretroviral há 6 meses. Está assintomática e sem sinais clínicos de patologias. Os exames de rotina mostram contagens de LT-CD4+ acima de 500 células/mm³ e carga viral indetectável. Ela refere início de um relacionamento com parceiro soropositivo de 35 anos de idade há 1 mês. Refere, ainda, que o parceiro tem dois filhos vivos saudáveis e que o casal não deseja ter filhos. Nessa situação, está indicado"},"A":{"antes_md5":"d636d2c870768d79a456e8e00e572d27","depois":"realização de laqueadura tubária associada ao uso de preservativo."},"B":{"antes_md5":"b85b9fc7705dfae08b5a5af3b0627d2f","depois":"uso de anticoncepcional hormonal associado ao uso de preservativo."},"C":{"antes_md5":"90e5836f1f30f6d4f0ab0620fc2a7900","depois":"uso do Dispositivo Intrauterino (DIU) de cobre."},"D":{"antes_md5":"6ac69ef2ee4eb65ec7976bbfc658ebbd","depois":"realização de vasectomia."}}},{"id":"revalida_2022_1_q050","code":"REV-2022.1-Q050","campos":{"A":{"antes_md5":"c64ab904627f5b4bce5112739ea545da","depois":"solicitar PSA e, se alterado, realizar o toque retal."},"B":{"antes_md5":"9e4d3454ca61029fbe87cdf44ed6cf45","depois":"solicitar PSA associado à realização do toque retal."},"C":{"antes_md5":"bc9858e7acfc0b615c63e1bdb25beae2","depois":"solicitar PSA e, se alterado, encaminhar ao urologista para a realização do toque retal."},"D":{"antes_md5":"9d2e248d79eb81fb6fe8405cc0257ef8","depois":"individualizar e compartilhar a decisão frente aos riscos e benefícios associados ao rastreamento."}}},{"id":"revalida_2022_1_q051","code":"REV-2022.1-Q051","campos":{"A":{"antes_md5":"ed2edf729afc0b4046a14d1f13838b90","depois":"tuberculose extrapulmonar."},"B":{"antes_md5":"54f5a7f482106dd62937a483ddca3439","depois":"tuberculose pulmonar latente."},"C":{"antes_md5":"4c7b645e3e561e357597e76b67f32489","depois":"tuberculose pulmonar pós-primária."},"D":{"antes_md5":"ee6739d9ade7f3f7abeb06b32fe220ff","depois":"infecção primária por Mycobacterium tuberculosis."}}},{"id":"revalida_2022_1_q052","code":"REV-2022.1-Q052","campos":{"A":{"antes_md5":"10a174760393c3d898f3e5dc39fb8f76","depois":"pedir uma radiografia do tornozelo para avaliar a fratura."},"B":{"antes_md5":"297aed451fe0d2fa5382957cee1523e2","depois":"aplicar calor local e encaminhar a paciente para avaliação do ortopedista."},"C":{"antes_md5":"935c204e459b3c86d196bac8fabdfefa","depois":"iniciar fisioterapia motora precoce e solicitar o parecer de um ortopedista."},"D":{"antes_md5":"3909301c6a1ab7bfb7cb2694afe808fd","depois":"imobilizar o membro afetado e medicar a paciente com anti-inflamatório."}}},{"id":"revalida_2022_1_q053","code":"REV-2022.1-Q053","campos":{"A":{"antes_md5":"309c0378ed119312d71e5661e86cb8f7","depois":"Caso o recém-nascido apresente boa vitalidade, o clampeamento imediato do cordão evita a hemorragia intracraniana e a enterocolite necrosante."},"C":{"antes_md5":"96be024638482f5590b80948374ff38c","depois":"Caso o recém-nascido não apresente boa vitalidade, realizam-se o clampeamento imediato de cordão, a colocação de touca dupla e saco plástico, visando-se manter a temperatura axilar > 37,5 °C para proteção de lesão cerebral em paciente asfixiado."}}},{"id":"revalida_2022_1_q054","code":"REV-2022.1-Q054","campos":{"A":{"antes_md5":"1d56c6d20998905506cff4107af0e617","depois":"Encaminhar o casal para programa de adoção."},"B":{"antes_md5":"c9e59e4ceccc15bb7830271b7dcaded1","depois":"Prescrever indução de ovulação para reprodução assistida."},"C":{"antes_md5":"e86f9ad498a893a522c1353022d34a6f","depois":"Encaminhar a paciente para cirurgia de recanalização tubária."},"D":{"antes_md5":"1e22a53776e03e4f00b1619cde0d0092","depois":"Solicitar exames para excluir outros fatores de infertilidade."}}},{"id":"revalida_2022_1_q055","code":"REV-2022.1-Q055","campos":{"statement":{"antes_md5":"3868ce3e33f3275e32c1b9ffeb438469","depois":"Um homem com 24 anos de idade realiza acompanhamento médico regular na Unidade de Saúde da Família (USF) de referência. Possui diagnóstico de HIV há 1 ano, sendo acompanhado em Centro de Saúde de Referência municipal para HIV/AIDS. Hoje, busca atendimento na USF com queixa de perda de peso nos últimos 3 meses, nota que as bermudas estão folgadas. Durante a anamnese, informou que há 3 semanas está com tosse, ocasionalmente apresentando sudorese noturna. Traz consigo exames laboratoriais e de imagem realizados há cerca de 7 dias. Radiografia de tórax com presença de infiltrados e cavidades em lobo superior direito. Prova tuberculínica positiva. Baciloscopia de escarro com presença de raros bacilos álcool-ácido resistente (BAAR). A região onde se encontra a USF apresenta índices elevados de Tuberculose, Paracoccidioidomicose, Criptococose e Toxoplasmose. Diante do quadro apresentado, o novo diagnóstico e os exames complementares adequados para comprová-lo são, respectivamente,"},"A":{"antes_md5":"c15b4baa4d31469923e6ffa63d01fbbf","depois":"criptococose; sorologia."},"B":{"antes_md5":"0f28d91a08cda2c2896f4952c0680900","depois":"paracocciodioidomicose; exame a fresco de escarro."},"C":{"antes_md5":"51ccf8507abb11526745a9c5d9336f0e","depois":"toxoplasmose; tomografia, imununofluorescência indireta e teste imunoenzimático (ELISA)."},"D":{"antes_md5":"3d87659163e9465b216c900e4f8fcd65","depois":"tuberculose pulmonar; teste rápido molecular para tuberculose (TRM-TB), cultura de escarro e teste de sensibilidade."}}},{"id":"revalida_2022_1_q056","code":"REV-2022.1-Q056","campos":{"A":{"antes_md5":"3203716458ff5682e474baf43fcc0904","depois":"Solicitar cintilografia de tireoide."},"B":{"antes_md5":"46f7bc49a592271f86fbbdabc6b68e9a","depois":"Solicitar ultrassonografia de tireoide."},"C":{"antes_md5":"65ad37eee5f375f2bcfcda3d623195ed","depois":"Encaminhar a paciente para cirurgia."},"D":{"antes_md5":"88d207efe42996ac12a174799826f377","depois":"Solicitar punção aspirativa por agulha fina."}}},{"id":"revalida_2022_1_q057","code":"REV-2022.1-Q057","campos":{"statement":{"antes_md5":"8f32eb0f22a8a1039e21624a70ea20a9","depois":"Uma paciente com 35 anos de idade vem apresentando dor em região lombar direita, associada a náuseas e vômitos de início súbito há 4 horas. Nesse período, nega febre e refere vários episódios semelhantes anteriores. Ao exame físico, apresenta apenas sinal de Giordano positivo à direita. Realizou tomografia de abdome e pelve que mostrou cálculo de 1,2 cm, localizado em junção ureteropiélica direita e de densidade de 1.500 UH. Resultado do exame de Elementos Anormais e Sedimentos (EAS) na urina mostrou apenas hematúria microscópica discreta. Em relação ao cálculo, entre as condutas a seguir, a mais indicada é"},"B":{"antes_md5":"8f11931a0f162275fb88aa710262dbd5","depois":"pielolitotomia cirúrgica."},"C":{"antes_md5":"88eb15b27db34f8d45e246f9120bef60","depois":"litotripsia extracorpórea."},"D":{"antes_md5":"a1d3667806dd5d838def2de6107c0786","depois":"terapia expulsora do cálculo com hidratação e alfa-bloqueadores."}}},{"id":"revalida_2022_1_q058","code":"REV-2022.1-Q058","campos":{"statement":{"antes_md5":"778c2d59fd041d6be77ec1df95aa07f5","depois":"Uma criança com 4 anos de idade, do sexo masculino, é atendida no serviço de emergência pública de sua cidade em decorrência de quadro de náuseas, vômitos e dor abdominal há cerca de 2 horas. A mãe refere que a criança vem perdendo peso há aproximadamente 2 meses e apresentando aumento de apetite e diurese nesse período. O desenvolvimento da criança é adequado para a idade. Ao exame físico, o paciente mostra-se acordado e colaborativo, apresentando hálito cetônico, hipocorado 1+/4+, desidratado 3+/4+ e taquipneico, abdome difusamente doloroso, mas sem sinais de irritação peritoneal. A ausculta respiratória e a cardiovascular apresentam-se sem anormalidades. Exames laboratoriais evidenciam glicemia = 350 mg/dL, gasometria com pH = 7,20; pCO₂ = 25 mmHg; pO₂ = 80 mmHg ; Bicarbonato = 10 mEq/L. O resultado do exame de urina revela cetonúria. Cerca de 4 horas após início de tratamento com reposição hídrica e insulina 0,1 UI/kg/h, o paciente passa a apresentar redução do nível de consciência associada a bradicardia. Considerando o caso clínico descrito, o tratamento mais adequado para a complicação apresentada por esse paciente deve ser feito com"},"A":{"antes_md5":"ec639c16a38bc9d4acfbcf63cf18c1da","depois":"bicarbonato, 1 mEq/kg, intravenoso."},"B":{"antes_md5":"825f0c331760cead80bac0a3c01d7cbb","depois":"flush de 200 mg/kg de glicose, intravenoso."},"C":{"antes_md5":"4608c9b7e1f5c14908d7375e4423f567","depois":"manitol, na dose de 0,5 a 1,0 g/kg, intravenoso."},"D":{"antes_md5":"432943dc357771bedd6c63df7fa5e438","depois":"40 mEq de potássio por litro de solução, intravenoso."}}},{"id":"revalida_2022_1_q059","code":"REV-2022.1-Q059","campos":{"statement":{"antes_md5":"8b86794314ec6dac51479f40c2f88fc5","depois":"Uma adolescente com 12 anos de idade, acompanhada de sua mãe, chega ao plantão hospitalar com sangramento abundante. A mãe afirma que a menarca de sua filha ocorreu há 6 meses. A adolescente relata ser a terceira menstruação nesse intervalo e nega contato sexual prévio. Ao exame ginecológico, não se observam anormalidades e o hímen está íntegro. Considerando esse quadro clínico, a causa mais provável de sangramento uterino anormal da paciente é"},"A":{"antes_md5":"8eeebad43e767ce56ad3b99bbd507fe6","depois":"anovulação."},"B":{"antes_md5":"854848d4500d7bb4094225a5df0fd3a5","depois":"doença von Willebrand."},"C":{"antes_md5":"05d6fd9fde16387111892eceac14147e","depois":"hipogonadismo hipogonadotrófico."},"D":{"antes_md5":"b7531a90a48bcad1bd83dbf6d1f9859a","depois":"púrpura trombocitopênica idiopática."}}},{"id":"revalida_2022_1_q060","code":"REV-2022.1-Q060","campos":{"A":{"antes_md5":"fa18a3a71f48c908f641ba67f84df9c1","depois":"a ressecção da margem lateral da unha deve ser realizada com tesoura reta, preservando-se a matriz ungueal."},"B":{"antes_md5":"06a8f73f1bc48d4b0740af2d7053addd","depois":"o bloqueio digital deve ser realizado com lidocaína com vasoconstritor, por ser um procedimento muito doloroso."},"C":{"antes_md5":"d29b3685f8767b295bcfb51dfd6d04bc","depois":"a introdução da tentacânula deve ser realizada a cerca de 3 mm da margem lateral, longitudinalmente até a matriz."},"D":{"antes_md5":"2e5225ebdaa9666967831e5332633d84","depois":"o tecido de granulação pode ser preservado, não havendo necessidade de ressecá-lo, pois não há sinais de infecção."}}},{"id":"revalida_2022_1_q061","code":"REV-2022.1-Q061","campos":{"A":{"antes_md5":"848f7290089e29f3e3ef4f91e7d23233","depois":"a falta de resposta ao broncodilatador sugere o diagnóstico de asma nessa paciente."},"B":{"antes_md5":"195ebae7941e533bfa4759ebff33c3e7","depois":"os resultados da espirometria estabelecem o diagnóstico de doença pulmonar obstrutiva crônica nessa paciente."}}},{"id":"revalida_2022_1_q062","code":"REV-2022.1-Q062","campos":{"statement":{"antes_md5":"b3f505bd200ee74424b5b301f8933a78","depois":"Uma paciente com 68 anos de idade, tabagista de longa data, foi encaminhada pelo médico da Unidade Básica de Saúde (UBS) para atendimento em ambulatório de cirurgia. O médico da UBS forneceu relatório afirmando que a paciente apresenta dor em região superior do abdome, que irradia para dorso, de forte intensidade, há cerca de 2 meses, associada a perda ponderal de quatro quilos, queda do estado geral e início de diabetes nesse mesmo período. A paciente relata prurido no corpo e, ao exame, apresenta icterícia moderada (2+/4+). Paciente sem comorbidades prévias. Considerando o caso apresentado, qual a principal hipótese diagnóstica e o exame de imagem inicial a ser solicitado?"},"A":{"antes_md5":"b30d878fdd6a4cdf9ac498048001cb87","depois":"Câncer de pâncreas; ultrassom de abdome."},"B":{"antes_md5":"2e6c5090c80ab88d3811ddab145ca0bc","depois":"Câncer de vias biliares; ressonância nuclear magnética de abdome."},"C":{"antes_md5":"a4cd0f682b84ab6f3fee36ab44b557a3","depois":"Câncer de fígado; tomografia computadorizada de abdome com contraste venoso."},"D":{"antes_md5":"0f3fdcc9262ff44a964ced732e1d521e","depois":"Coledocolitíase; colangiopancreatografia retrógrada endoscópica com papilotomia."}}},{"id":"revalida_2022_1_q063","code":"REV-2022.1-Q063","campos":{"A":{"antes_md5":"57ceb27c3f5228aabc959d7874f9632c","depois":"alterado, uma vez que foi realizado de acordo com a técnica preconizada."},"B":{"antes_md5":"dc723bf7ba049e5b219d877157861c5f","depois":"normal, visto que a saturação pós-ductal é superior à pré-ductal."},"C":{"antes_md5":"99cf031ba1a092ed9c32b9c768e41811","depois":"inválido, já que foi feito antes da idade gestacional indicada."},"D":{"antes_md5":"b6a6534ffe1692318cb2ef7da497eaac","depois":"inválido, pois foi realizado antes do período preconizado."}}},{"id":"revalida_2022_1_q064","code":"REV-2022.1-Q064","campos":{"statement":{"antes_md5":"8af2e7d0591784c14a2b5ebf96ab7f31","depois":"Uma gestante com 35 anos de idade, gesta: 4, para: 3, aborto: 0 (três partos vaginais anteriores), iniciou pré-natal com 11 semanas, ocasião em que realizou todos os exames recomendados e nenhuma anormalidade foi detectada. Com 35 semanas, realizou novos exames, sendo diagnosticado HIV, com carga viral de 2.000 cópias/mL. Nessa mesma idade gestacional, iniciou terapia antirretroviral. Nesse caso, a conduta a ser adotada para essa gestante é"},"B":{"antes_md5":"99235c00c4f97541ac4b2cdf3d159756","depois":"programar parto cesariana para a 38ª semana de gestação e iniciar zidovudina endovenosa pelo menos 3 horas antes do procedimento."},"C":{"antes_md5":"7ff5cab90f050f32f067869dac4cea26","depois":"realizar parto cesariana na 40ª semana e prescrever zidovudina injetável para ser administrada 1 hora antes do procedimento."},"D":{"antes_md5":"0225ab983d3360c01c1e21c7409f7bd1","depois":"aguardar início espontâneo do parto vaginal até 40 semanas e usar zidovudina endovenosa durante todo o período do trabalho de parto."}}},{"id":"revalida_2022_1_q065","code":"REV-2022.1-Q065","campos":{"A":{"antes_md5":"e0d1f67e1e0309d75d07fb7f3ed699a5","depois":"nos benefícios de uma mudança, buscando pressionar a paciente a iniciar um novo estilo de vida."},"B":{"antes_md5":"5511567e5622f960c3149141c2bcb3d5","depois":"na resistência à mudança, confrontando e debatendo com a paciente sobre a importância de novos hábitos."},"C":{"antes_md5":"9f28164e190c908ad63cc871c8e18c25","depois":"nas consequências dos fatores de risco atuais, explicando com detalhes os malefícios da não mudança de hábitos."}}},{"id":"revalida_2022_1_q066","code":"REV-2022.1-Q066","campos":{"statement":{"antes_md5":"d398929c542d8d5b6491da449c523351","depois":"Um homem com 26 anos de idade comparece à consulta na atenção básica por “impinge”. Ele refere que seu cachorro também está com lesões descamativas de pele, apresentando inclusive áreas de alopecia. Ao exame físico, verificam-se manchas eritematosas descamativas em forma de anel, que poupam a região central, localizadas em tronco, face e braços. O paciente relata ter usado clotrimazol, sem ter obtido melhora. Para esse paciente, a conduta imediata deve ser"},"A":{"antes_md5":"6756f758e59790dff471943280cfe9ec","depois":"investigar possível infecção fúngica por meio da avaliação de KOH a 10% ou cultura fúngica por raspagem da pele; se o teste for positivo, tratar com terbinafina oral por 14 dias."},"C":{"antes_md5":"74bff6ff3e12868f7c6acf657909fc9f","depois":"tratar com clotrimazol tópico por 3 semanas, visto que, pelas características das lesões de pele, muito sugestivas de lesão fúngica, não há necessidade de investigação adicional."}}},{"id":"revalida_2022_1_q067","code":"REV-2022.1-Q067","campos":{"statement":{"antes_md5":"4ea634329fd84181b8c8b13e0266ae64","depois":"Uma paciente com 19 anos de idade apresenta-se no ambulatório com queixa de “caroço no pescoço”. Nega comorbidades ou uso de medicações. Ao exame, há nódulo palpável em lobo esquerdo da tireoide, medindo aproximadamente 2,5 x 2 cm, endurecido, não pulsátil, sem frêmito, indolor, aderido à musculatura infra-hioidea. Há, ainda, alguns linfonodos cervicais palpáveis à esquerda. Sem outras queixas. Diante desse quadro clínico, qual é o diagnóstico mais provável e o exame inicial a ser solicitado?"},"A":{"antes_md5":"835d41cf7a0478f181c8b6196f66abc6","depois":"Bócio; tomografia computadorizada de pescoço, com contraste."},"B":{"antes_md5":"469abf127c220c9c30f487eb30fde363","depois":"Tireoidite de Hashimoto; ressonância nuclear magnética de pescoço."},"C":{"antes_md5":"dc128d319c33ddf93413e14512ec0398","depois":"Cisto de conduto tireoglosso; cintilografia da tireoide com iodo radioativo."},"D":{"antes_md5":"12f674d57a01c7d9da28808fd12bffec","depois":"Câncer de tiréoide; ultrassonografia de pescoço com Doppler da tireoide e punção aspirativa por agulha fina."}}},{"id":"revalida_2022_1_q068","code":"REV-2022.1-Q068","campos":{"statement":{"antes_md5":"9b1572f95af4b2f30676e56883db9157","depois":"Uma escolar com 8 anos de idade, acompanhada da mãe, chega à emergência com dor abdominal intensa, iniciada há 2 dias, com piora progressiva. A paciente apresenta vômitos biliosos, que não melhoram com a medicação, e distensão abdominal. A mãe relata que, há 1 semana, a filha eliminou verme e está em tratamento de anemia. O exame físico mostrou massa cilíndrica na região periumbilical e ausculta débil da peristalse. O resultado da radiografia do abdome apresentou níveis hidroaéreos no intestino delgado e sombra radiolúcida com forma e aparência de “feixe de charuto”. Diante desses dados, considerando a principal hipótese diagnóstica para o caso, a conduta imediata, além da hidratação da criança, é"},"A":{"antes_md5":"c13bbfb56130708e52591b01b2191774","depois":"realizar descompressão gástrica com sonda nasogástrica e administrar óleo mineral."},"B":{"antes_md5":"7528a7254dbb22cccef9c2246730b2d0","depois":"realizar enema com solução salina hipertônica e administrar ivermectina."},"C":{"antes_md5":"d5a2379095540544b4f9548bc4846f99","depois":"instalar sonda nasogástrica aberta, para drenagem, e administrar piperazina."},"D":{"antes_md5":"2d93ad68e5303c49428d2e6ff5185923","depois":"suspender a ingestão oral e indicar o tratamento cirúrgico."}}},{"id":"revalida_2022_1_q069","code":"REV-2022.1-Q069","campos":{"A":{"antes_md5":"e577374219dd38e90508073f8a317e63","depois":"realizar a vacinação contra influenza em dose única imediata e administrar nova dose de dTpa."},"B":{"antes_md5":"4f17996327d9d05303be730abf3dbeb1","depois":"administrar nova dose de dTpa, não havendo necessidade de nova vacinação contra influenza."},"C":{"antes_md5":"d4a32ba815bd23cd96989a2c33c2488e","depois":"realizar vacinação contra influenza em 2 doses (imediata e após 30 dias) e administrar nova dose de dTpa."},"D":{"antes_md5":"e07213220ee7c23fa7179f7b733db9ef","depois":"realizar vacinação contra influenza em dose única imediata, não havendo indicação de nova dose da dTpa."}}},{"id":"revalida_2022_1_q070","code":"REV-2022.1-Q070","campos":{"A":{"antes_md5":"507cc1180e9f1ecbf04b90a023628acd","depois":"a tríplice viral juntamente com a tetraviral."},"B":{"antes_md5":"2796f8eb278144b48e1fdec708c513a8","depois":"o reforço da pneumocócica conjugada."},"C":{"antes_md5":"80b8af481d7c2c5433f9af1cdab52822","depois":"o reforço da meningocócica C conjugada."},"D":{"antes_md5":"ee36ca5aa438d0578343258d006e265c","depois":"a segunda dose da tríplice viral + varicela."}}},{"id":"revalida_2022_1_q071","code":"REV-2022.1-Q071","campos":{"statement":{"antes_md5":"a3cab5aba52cdf34db4e75e30aa0e31b","depois":"Uma mulher com 33 anos de idade procura o ambulatório de clínica médica devido a dores articulares há 3 meses. Refere o acometimento de mãos (interfalangeanas proximais e metacarpofalangeanas), punhos e joelhos. Ao exame físico, apresenta sinais de artrite nessas articulações. Foram solicitados exames laboratoriais para a investigação diagnóstica e os resultados são apresentados a seguir. Valor encontrado Valor de Referência Exame Hemoglobina 12-14 g/dL 10 g/dL 36-42% Hematócrito 30% 80-100 fL 90 fL VCM HCM 27-32 pg 30 pg RDW 11,5-15% 14% Leucócitos 4 mil/mm3 5-10 mil/mm3 Bastões 1% 0-5% Neutrófilos 45-75% 74% Linfócitos 22-40% 20% Eosinófilos 5% 1-5% 150-400 mil/mm3 130 mil/mm} Plaquetas Diante desses achados clínicos e laboratoriais, quais são, respectivamente, o autoanticorpo relacionado ao FAN apresentado e o diagnóstico pertinente ao caso?","sem_tabela_md5":"2772125d376e19f10f6056a6dba58d6f"},"A":{"antes_md5":"769521818a02efee26e5b9e109390037","depois":"AntiDNA nativo; lúpus eritematoso sistêmico."},"C":{"antes_md5":"9c24aae68e40d870782b8e2bda0f871d","depois":"AntiScl-70; esclerose sistêmica."}}},{"id":"revalida_2022_1_q072","code":"REV-2022.1-Q072","campos":{"A":{"antes_md5":"b08b358190495c1f2094e234e18c2766","depois":"documentos referentes aos procedimentos administrativos, que são de guarda, responsabilidade e propriedade do hospital."},"B":{"antes_md5":"a3b379e7e606cf3eeb46153a4b74e427","depois":"documentos técnicos e administrativos referentes à internação, que são de responsabilidade, guarda e propriedade do hospital."},"C":{"antes_md5":"e663b7d8d1d9e347a032ee3d3200c499","depois":"documentos técnicos e administrativos referentes à internação hospitalar, que são de guarda e responsabilidade do hospital, mas de propriedade do paciente."},"D":{"antes_md5":"6c7f43f6987af3aae169d3234db57395","depois":"documentos técnicos referentes somente aos atos médicos executados, que são de guarda e responsabilidade do hospital, mas de propriedade do paciente."}}},{"id":"revalida_2022_1_q073","code":"REV-2022.1-Q073","campos":{"A":{"antes_md5":"88b1a481a8a9decbf2ebc35eb715dd91","depois":"escarlatina."},"B":{"antes_md5":"bdb8b8ae19cfdbbd43470575c53e286b","depois":"mononucleose."},"C":{"antes_md5":"7b88ba240efae6caa6bfba6dc5af2595","depois":"eritema infeccioso."},"D":{"antes_md5":"2c1c28b4151a6f9ee7c1fcb8505a6e04","depois":"doença de Kawasaki."}}},{"id":"revalida_2022_1_q074","code":"REV-2022.1-Q074","campos":{"statement":{"antes_md5":"d1f168d63c27667f64816bbf0144b523","depois":"Uma paciente com 26 anos de idade, gesta: 2, para: 2, aborto: 0, utilizando contraceptivo oral combinado regularmente, comparece à Unidade Básica de Saúde para verificação do resultado de exame de citologia oncótica cérvico-vaginal realizado há 1 mês. Não há queixas ou alterações descritas no prontuário do atendimento anterior quando do exame ginecológico. No laudo, descreve-se a presença de lesão intraepitelial escamosa de baixo grau (LSIL). Em relação ao resultado do exame de citologia oncótica cérvico-vaginal da paciente, segundo o Instituto Nacional do Câncer/Ministério da Saúde, qual deve ser a conduta?"},"A":{"antes_md5":"ad904805388cebbb2068583c93f28a72","depois":"Repetir a coleta para exame da citologia em 6 meses."},"B":{"antes_md5":"aec194803b8466df26d96a2a94c3b3dd","depois":"Realizar nova coleta da citologia em 1 ano."},"C":{"antes_md5":"0d8cfd45d175b7b7a661b45819afc192","depois":"Solicitar pesquisa do tipo e da classe viral."},"D":{"antes_md5":"35eb9546cbe4793336fde5ab6a9158a3","depois":"Encaminhar para colposcopia e biópsia."}}},{"id":"revalida_2022_1_q075","code":"REV-2022.1-Q075","campos":{"statement":{"antes_md5":"0d7a20ad6a6195db55fbda90486d88cd","depois":"Na sua primeira semana em uma Unidade Básica de Saúde (UBS), o médico de família se reúne com os outros profissionais da equipe e realiza visitas no bairro para conhecer melhor o território. Descobre que na região da UBS há várias indústrias de extração mineral, que produzem poeira de sílica e talco. Revisando alguns prontuários clínicos, o médico constata que há uma prevalência bastante elevada de doenças respiratórias, principalmente a silicose. Entre as medidas de prevenção secundária, o médico deve recomendar para todas as pessoas da sua comunidade que apresentarem silicose a realização de exames para"},"A":{"antes_md5":"f4ec071d81987b6b1b87ba9f9c5a3b7f","depois":"leucemia."},"B":{"antes_md5":"f8744a1364c43e79be3f5ac4c101eaea","depois":"tuberculose."},"C":{"antes_md5":"3a98768e4a2783a88a6abe1dd9cc5969","depois":"câncer de bexiga."}}},{"id":"revalida_2022_1_q076","code":"REV-2022.1-Q076","campos":{"A":{"antes_md5":"0ce217f2843bfbe883ad2f285101f2fd","depois":"tratamento da paciente com esquema para sífilis secundária, não havendo necessidade de realização de outro teste."},"B":{"antes_md5":"a679d19de3579883cfb17f4139a056c0","depois":"teste treponêmico e aguardar o resultado antes de iniciar tratamento da paciente."},"C":{"antes_md5":"7ba30429e6e82919d30378cc08f5e61d","depois":"teste não treponêmico e tratar a paciente com esquema de sífilis latente tardia."},"D":{"antes_md5":"c3e44c8427f39ea8b02d072ca9132989","depois":"teste de rastreamento para HIV e tratar a paciente com esquema para sífilis primária."}}},{"id":"revalida_2022_1_q077","code":"REV-2022.1-Q077","campos":{"A":{"antes_md5":"d1c0d4ffdc3bd1fe43de71eae6cd808b","depois":"hérnia inguinal indireta; encaminhamento ao cirurgião para correção cirúrgica eletiva."},"B":{"antes_md5":"68e472f96fb36ed11598170d50abf568","depois":"hérnia inguinal direta; encaminhamento ao cirurgião para correção cirúrgica de urgência."},"C":{"antes_md5":"c4a411a4c6927f1e853133b72dcb7a6c","depois":"hidrocele comunicante à direita; encaminhamento ao cirurgião para correção cirúrgica eletiva."},"D":{"antes_md5":"79d0a432f5fe0dc7762d1b6ac72b01e3","depois":"hidrocele septada à direita; encaminhamento ao cirurgião para correção cirúrgica de urgência."}}},{"id":"revalida_2022_1_q078","code":"REV-2022.1-Q078","campos":{"A":{"antes_md5":"301c756921261ba3d93eab20ba6e78c1","depois":"Manometria anorretal; relaxamento do esfíncter anal interno."},"B":{"antes_md5":"0f7054aca6ab477bd85e48bb78256940","depois":"Biópsia retal; presença ou diminuição do número de células ganglionares."},"C":{"antes_md5":"63f30c3878545513479a173a98feb5eb","depois":"Enema contrastado; dilatação do segmento colônico com a inervação preservada."},"D":{"antes_md5":"8ea7bf6a20d3fc64d396be3b136ee9a1","depois":"Radiografia simples do abdome; calibre do reto maior que o do segmento colônico à montante."}}},{"id":"revalida_2022_1_q079","code":"REV-2022.1-Q079","campos":{"statement":{"antes_md5":"54a213d5873df8c2eacaa8e45343fc40","depois":"Uma paciente com 37 anos de idade, primigesta, em atendimento pré-natal em unidade ambulatorial secundária, apresenta amenorreia de 12 semanas. Tem história de hipertensão arterial crônica e refere uso irregular de captopril. Na consulta médica, apresenta-se sem queixas, com pressão arterial de 150 x 100 mmHg, mantida após 30 minutos de decúbito lateral esquerdo; a proteinúria de fita é negativa. O exame obstétrico está compatível com 12 semanas de gestação. Nesse caso, a conduta adequada em relação à pressão arterial da paciente é"},"A":{"antes_md5":"6963ff969d1c21a0a420ad168b8a9902","depois":"solicitar internação e administração de hidralazina endovenosa."},"B":{"antes_md5":"98f64bf9557ad7f8a666debcfa301f8a","depois":"orientar o uso regular do captopril e fazer curva pressórica."},"C":{"antes_md5":"39b298fd125fc72b5e2a89383e0b23e9","depois":"orientar dieta hipossódica e iniciar metildopa via oral."},"D":{"antes_md5":"cce83dc31893599e6799aee0b31819e0","depois":"orientar dieta hipossódica e fazer curva pressórica."}}},{"id":"revalida_2022_1_q080","code":"REV-2022.1-Q080","campos":{"A":{"antes_md5":"f8e09b4583fc2185be2d212574be82e8","depois":"somente os casos positivos."},"B":{"antes_md5":"1cff641f19fb791e41f43ecaa542120e","depois":"coletivamente a comunidade."},"C":{"antes_md5":"3fda594db16e155624cc70beb2fa1845","depois":"os casos positivos e conviventes."},"D":{"antes_md5":"abb796275f316c6347191cd551067b7f","depois":"somente os casos confirmados por meio de um segundo exame."}}},{"id":"revalida_2022_1_q081","code":"REV-2022.1-Q081","campos":{"statement":{"antes_md5":"236b19e7b5f41470de12a15b18d869d7","depois":"Um homem com 61 anos de idade, hipertenso, atendido em unidade de saúde, tem febre, tosse com secreção amarelada, dor torácica à direita ventilatório-dependente, dispneia aos esforços moderados e hiporexia há 3 dias. É adequadamente vacinado para pneumococo e não tem história de internações no último ano. Ao primeiro exame, apresentou-se orientado, hidratado, com temperatura axilar = 38,5 °C, frequência cardíaca (FC) = 90 batimentos por minuto (bpm), pressão arterial (PA) = 130 x 80 mmHg, frequência respiratória (FR) = 22 incursões respiratórias por minuto (irpm), sem esforço respiratório, frêmito toracovocal diminuído e estertores crepitantes no terço inferior de hemitórax direito. O resultado da oximetria de pulso em ar ambiente foi de 96% e o da radiologia simples de tórax mostrou infiltrado em lobo inferior direito com derrame pleural de 2 cm em decúbito lateral. Foi-lhe prescrito amoxicilina + clavulanato para tratamento ambulatorial e solicitada punção de líquido pleural. No terceiro dia de tratamento, o paciente relatou melhora da febre e da dispneia, mas manutenção da tosse, da dor torácica e da hiporexia, e apresentou os seguintes resultados: temperatura axilar = 37,2 °C, FC = 80 bpm, PA = 130 x 70mmHg, FR = 18 irpm, oximetria de pulso em ar ambiente = 98%. O resultado da punção torácica, guiada por ultrassom, estimou o derrame em 200 mL, cuja análise mostrou líquido amarelo-citrino, 2.300 células com predomínio de neutrófilos, pH = 7,3, glicose = 60 mg/dL, LHD = 300 U/L, proteína = 4 g/L, Gram: não se visualizaram bactérias. A amostra sérica colhida no dia da punção mostrou glicose = 80 mg/dL (valor de referência [VR]= 60-99 mg/dL), proteínas totais = 6,6 g/dL (VR = 6,4-8,3 g/dL), LDH = 400 (VR = 180-450 U/L). Diante desse quadro clínico e dos dados apresentados, a abordagem adequada para o paciente é"},"A":{"antes_md5":"382747d50a59d2116b553ec1240bf9d5","depois":"referenciar o paciente para a assistência hospitalar para drenagem de tórax."},"B":{"antes_md5":"058ba00e3db363466f6f25aa8b202a5e","depois":"manter o tratamento com amoxicilina + clavulanato e repetir o estudo radiológico em 1 semana."},"C":{"antes_md5":"802ed9e458a24ce03ef31dbd8020eda9","depois":"suspender a amoxicilina + clavulanato, prescrever levofloxacina e reavaliar o paciente em 3 dias."},"D":{"antes_md5":"b7f4bdf8e2022fce650f461f343667bc","depois":"manter o tratamento com amoxicilina + clavulanato, colher bacilos álcool-ácido resistente (BAAR) em escarro e reavaliar o paciente no final do tratamento."}}},{"id":"revalida_2022_1_q082","code":"REV-2022.1-Q082","campos":{"statement":{"antes_md5":"5f38f5d0238a499b5d25ae2b8488c0ab","depois":"Uma criança com 10 anos de idade, do sexo masculino, foi vítima de ferimento em região mentoniana após queda de skate no asfalto, há cerca de 90 minutos. Ao exame físico apresenta ferimento corto-contuso, transversal, na região submentoniana, com 3,0 cm de extensão, sangrante. Para fins de conduta médica imediata e mediata, trata-se de ferida"},"A":{"antes_md5":"2d922fb2bb5e23800e8424af89b22e70","depois":"limpa."},"B":{"antes_md5":"e2792648ae9f203f6235763e4921cb76","depois":"infectada."},"C":{"antes_md5":"e9e463d9a7b5584317d1489c247e7f79","depois":"contaminada."},"D":{"antes_md5":"4af186b630fc55cf669cef45bbb4ca0b","depois":"potencialmente contaminada."}}},{"id":"revalida_2022_1_q083","code":"REV-2022.1-Q083","campos":{"statement":{"antes_md5":"f0bedd504e07bbcbf069efd4434a8699","depois":"Um escolar do sexo masculino, residente em área rural, é encaminhado para um hospital de referência para investigação de quadro de febre irregular e prolongada, palidez, hepatoesplenomegalia e emagrecimento, insidiosos e progressivos, associados ao comprometimento do estado geral. Esteve internado em sua cidade de origem por 24 horas após apresentar epistaxe de grande intensidade e gengivorragia. Ao exame admissional, observam-se prostração, petéquias disseminadas em tronco e edema de membros inferiores. Em sua cidade de origem, foram realizados os exames inespecíficos, que demostraram anemia, leucopenia e plaquetopenia. Informa que o pai teve quadro semelhante há alguns meses. Entre os exames a serem realizados para se estabelecer o diagnóstico, é correto afirmar que"},"A":{"antes_md5":"bf3adc222309436b5bef5c7a076f0916","depois":"o exame sorológico por imunofluorescência indireta é o mais vantajoso no que se refere a custo e efetividade, sendo considerados positivos os títulos a partir da diluição 1:80."},"B":{"antes_md5":"5b68a805465a8d3dfdab041b299d34a6","depois":"a punção aspirativa esplênica é o método que oferece maior sensibilidade e menor risco, sendo o mais utilizado para a técnica de visualização direta do parasita."},"C":{"antes_md5":"43c268d63efd448378b0a0e962a224c8","depois":"a reação em cadeia da polimerase (PCR), técnica molecular, é de baixa sensibilidade quando comparada a técnicas por visualização direta."},"D":{"antes_md5":"8ebde0281925fdbcff48c8ed470da1d2","depois":"a dosagem de proteínas, na qual há forte inversão da relação albumina/globulina, é exame de alta sensibilidade e especificidade."}}},{"id":"revalida_2022_1_q084","code":"REV-2022.1-Q084","campos":{"A":{"antes_md5":"215d5c36726491a26fcaf322617ed377","depois":"identificar o agente etiológico da secreção cervical antes de iniciar o tratamento medicamentoso."},"B":{"antes_md5":"750a3c59380056d02592646dc366d901","depois":"encaminhar a paciente para tratamento em ambiente hospitalar com antibioticoterapia injetável."},"C":{"antes_md5":"686d31bc19605524e5479bf5e01c93de","depois":"instituir tratamento clínico ambulatorial de imediato para a paciente, com retorno em 48 horas para reavaliação."},"D":{"antes_md5":"c145f5f4b35e4da8fc5e29e7572f76c8","depois":"encaminhar a paciente para tratamento cirúrgico a fim de melhor avaliar o comprometimento do sistema reprodutivo."}}},{"id":"revalida_2022_1_q085","code":"REV-2022.1-Q085","campos":{"A":{"antes_md5":"943d0463db95724755fcb8ca92adbd9c","depois":"solicitar tomografia de tórax para investigar metástases pulmonares."},"C":{"antes_md5":"4d025e2a0bb450607e29d9aded37614d","depois":"encaminhar para emergência hospitalar se não houver melhora da dispneia com oxigenioterapia."},"D":{"antes_md5":"3f3794a91cb6b40b03413439b49f830e","depois":"instituir terapia de sedação paliativa se os sintomas físicos forem intoleráveis, graves e refratários."}}},{"id":"revalida_2022_1_q086","code":"REV-2022.1-Q086","campos":{"statement":{"antes_md5":"b29446868b5116b1384b3e0bae6d1aff","depois":"Uma mulher com 35 anos de idade, com asma moderada, é atendida em pronto atendimento e relata dispneia e sibilos há 1 dia. Refere que, em casa, inalou 2 jatos de salbutamol de 4/4 horas, sem melhora clinicamente relevante. Nega febre, cefaleia, dor torácica, rinorreia ou gotejamento pós-nasais e relata tosse seca intermitente. No pronto atendimento, está inicialmente agitada, frequência cardíaca (FC) = 115 batimentos por minuto (bpm), pressão arterial (PA) = 140 x 80 mmHg, frequência respiratória (FR) = 32 incursões respiratórias por minuto (irpm), sibilos difusos, oximetria de pulso = 91% em ar ambiente; peak flow < 50% do previsto. Após receber O2 suplementar 1 L/min, 3 aplicações de 4 jatos de salbutamol por via inalatória em intervalos de 20 minutos + prednisona 60 mg por via oral, continua agitada, apresentando FC = 100 bpm, PA = 120 x 70 mmHg, FR = 28 irpm, e mantendo sibilos difusos em ambos os hemitórax; oximetria de pulso = 89% em ar ambiente e 93% com O₂, peak flow mantém-se abaixo de 50%. O próximo passo adequado à abordagem dessa paciente é"},"A":{"antes_md5":"ffd751636e5420fedb8eb2d309df91af","depois":"mantê-la em observação no pronto atendimento e associar ipratrópio 4 jatos de 20/20 minutos e sulfato de magnésio 2 g intravenoso."},"B":{"antes_md5":"3df2ee7b28cccba3511e097c990650c2","depois":"mantê-la em observação no pronto atendimento e administrar nova dose de salbutamol, 4 jatos, em 1 hora."},"C":{"antes_md5":"0a54814950e379a8770bc7724cdad9c3","depois":"admiti-la em enfermaria com salbutamol + ipratrópio inalatórios, 4 jatos de cada um de 1/1 hora até a estabilização."},"D":{"antes_md5":"5e644c16bca1b8e95f8e2d903b241aca","depois":"realizar intubação orotraqueal com sequência rápida e mantê-la em ventilação mecânica até estabilização clínica."}}},{"id":"revalida_2022_1_q087","code":"REV-2022.1-Q087","campos":{"A":{"antes_md5":"8423cf59ac4252776bd0bd0218905e26","depois":"tumor de cólon direito."},"B":{"antes_md5":"be6c3034f86c9a0b93998a29e4d104e3","depois":"tuberculose intestinal."},"C":{"antes_md5":"8816ca648a5654791df6251e98efcbd9","depois":"doença diverticular do cólon."},"D":{"antes_md5":"21a1e40c6dba750b2919896a0e4f7182","depois":"doença inflamatória intestinal."}}},{"id":"revalida_2022_1_q088","code":"REV-2022.1-Q088","campos":{"A":{"antes_md5":"359c4973a3f0a92616d1552b875ccf72","depois":"Tomografia computadorizada."},"B":{"antes_md5":"0aa18e7c3e13b965782c6367e1f118ba","depois":"Endoscopia digestiva alta."},"D":{"antes_md5":"fcd6226eff04a0434e5c650d334bf16b","depois":"Ultrassonografia."}}},{"id":"revalida_2022_1_q089","code":"REV-2022.1-Q089","campos":{"A":{"antes_md5":"319a3f6e3622e56a9193305238a6614c","depois":"Ácido tranexâmico."},"B":{"antes_md5":"f20e0dec085af890d84c571648dd590f","depois":"Anti-inflamatório não esteroide."},"C":{"antes_md5":"6acd41b33bbd8f262b5ef88998743895","depois":"Anticoncepcional oral combinado."},"D":{"antes_md5":"14def1f4c2aa672e873227f488eb5920","depois":"Sistema Intrauterino (SIU) com liberação de levonorgestrel."}}},{"id":"revalida_2022_1_q090","code":"REV-2022.1-Q090","campos":{"statement":{"antes_md5":"6614768c54d3a1ea4addfb5b8df770d4","depois":"Uma mulher com 30 anos de idade vem a primeira consulta na Unidade Básica de Saúde queixando-se de tonturas, tremores, tensão muscular e relata que há 1 mês apresentou três crises de palpitações repentinas, acompanhadas de dor em hemitórax esquerdo, com duração de até meia hora e resolução espontânea. Nega doenças pregressas, tabagismo, etilismo ou uso de outras drogas. Relata que procurou serviços de emergência três vezes achando que teria um infarto. Traz resultados recentes e normais de hemograma, TSH, perfil lipídico completo, glicemia, troponina e CPK e eletrocardiograma. Acredita que esses exames foram insuficientes e pede outros exames para ver se o coração está bem. Por exercer a prostituição desde a adolescência, faz exames rotineiramente para infecções sexualmente transmissíveis, últimos há 15 dias e com resultados negativos. Usa Dispositivo Intrauterino (DIU) de cobre há 5 anos e preservativo. Não teve filhos ou abortamento. Apresenta sono reparador, exceto quando tem as crises. Nega ideação suicida. Desde o início da pandemia da COVID-19 não faz mais programas. Exame físico inalterado. Nesse caso, a melhor abordagem é"},"A":{"antes_md5":"e3fb04861c7d9c626b8865b2fecb938e","depois":"referenciar a paciente ao serviço de urgência e emergência para realização de novos eletrocardiogramas (ECG) e enzimas cardíacas e solicitar avaliação de especialistas focais."},"B":{"antes_md5":"ded51c8b220f0201c78ce77ac47f4c33","depois":"solicitar novos exames para descartar outras doenças orgânicas de base e iniciar tratamento farmacológico com betabloqueador e benzodiazepínico."},"C":{"antes_md5":"cb591fe8940470f7e89ad5bc998d299c","depois":"explicar que novos exames são desnecessários, indicar atividades físicas, apoio psicológico e retorno, em um continuum de complexidade de tratamento."},"D":{"antes_md5":"e78beddb9220099ecf1c7b79152824f6","depois":"explicar que novos exames são desnecessários, iniciar benzodiazepínico nas crises e antidepressivo tricíclico; indicar apoio psicológico e retorno em 6 semanas."}}},{"id":"revalida_2022_1_q091","code":"REV-2022.1-Q091","campos":{"A":{"antes_md5":"25b1e8cdc81c485e1bf58af15ccf1e57","depois":"hepatite B aguda; iniciar tratamento sintomático, evitando-se fármacos hepatotóxicos e de metabolismo hepático."},"D":{"antes_md5":"edf37e581a3304d9db166a59a399d7ed","depois":"hepatite B crônica agudizada; prescrever tenofovir ou entecavir, evitando-se fármacos hepatotóxicos e de metabolismo hepático."}}},{"id":"revalida_2022_1_q092","code":"REV-2022.1-Q092","campos":{"A":{"antes_md5":"f0d464832e2531b7dc0f97ad06d86f55","depois":"Traumatismo leve; solicitar tomografia de crânio e avaliação clínica seriada."},"B":{"antes_md5":"e9d60ba095f916469cf54955fa1f7671","depois":"Traumatismo moderado; solicitar tomografia de crânio e avaliação clínica seriada."},"C":{"antes_md5":"f1e520eef447b300b014394fecf40509","depois":"Traumatismo leve; solicitar avaliação clínica seriada e tomografia de crânio se a pontuação na escala de Glasgow for menor que 15 após 2 horas."},"D":{"antes_md5":"96d25c82aa1f6c7f3ca9aff1b00a4e07","depois":"Traumatismo moderado; solicitar avaliação clínica seriada e tomografia de crânio se a pontuação na escala de Glasgow for menor que 15 após 2 horas."}}},{"id":"revalida_2022_1_q093","code":"REV-2022.1-Q093","campos":{"A":{"antes_md5":"fcab1f4047c8639a39cb9aa271ab4fd0","depois":"realizar atriosseptostomia por balão."},"B":{"antes_md5":"fd7b1c345bf89fc99ab96e3193311a58","depois":"iniciar a administração de prostaglandina."},"C":{"antes_md5":"b654580f92054a5dd91aea67e2425653","depois":"encaminhar o paciente para cirurgia corretiva."},"D":{"antes_md5":"3b695b565c87dcfe65bb977efbe9cc4e","depois":"ventilar o paciente com uma FiO₂ entre 80 a 100%."}}},{"id":"revalida_2022_1_q094","code":"REV-2022.1-Q094","campos":{"A":{"antes_md5":"75830dd37c323ebde250dd15c19e9c0b","depois":"exérese da zona de transformação com alça de alta frequência."},"B":{"antes_md5":"9982222936151757683183b040a7c340","depois":"conização a frio do colo uterino com margem de segurança."},"C":{"antes_md5":"0e1a95980dcf3c14b39993840093ab7c","depois":"repetição da coleta da citologia oncótica em 6 meses."},"D":{"antes_md5":"11de60f0bbabcc3bf86c8d28448ea690","depois":"amputação do colo uterino com eletrocauterização."}}},{"id":"revalida_2022_1_q095","code":"REV-2022.1-Q095","campos":{"A":{"antes_md5":"b77380d9c9b9bc6f755c5d0320828120","depois":"promoção de reuniões com profissionais do Centro de Atenção Psicossocial infantil e familiares para esclarecer o manejo medicamentoso dos casos."},"B":{"antes_md5":"96c809ae331572abcabcc8bcae174417","depois":"escuta ativa das queixas trazidas pelos familiares, para a compreensão do problema e construção dialogada da solução."},"C":{"antes_md5":"830fc2c404b90cbf4d49cfadce27c5be","depois":"utilização pelos profissionais da Unidade Básica de Saúde de uma série de técnicas de convencimento dos familiares para evitar a medicalização do sofrimento das crianças."},"D":{"antes_md5":"ea22d870db7c51ff4186bcc1ea3eb1f0","depois":"elaboração de uma série de palestras informativas, com exposição das melhores evidências científicas para o tratamento das doenças neurodegenerativas da infância."}}},{"id":"revalida_2022_1_q096","code":"REV-2022.1-Q096","campos":{"A":{"antes_md5":"3a8e129a63f5a55ddd88449a9b67dd15","depois":"realização de tomografia de pelve e abdome."},"B":{"antes_md5":"b2bbdc3da4fc5d46ee0b635bc9be8f62","depois":"repetição, de imediato, de biópsia de próstata."},"C":{"antes_md5":"8a075bc03431c3743ba594245cc7d10c","depois":"repetição da dosagem de PSA em 6 meses."}}},{"id":"revalida_2022_1_q097","code":"REV-2022.1-Q097","campos":{"A":{"antes_md5":"41f3c26a8453e341c32aa51068990aaf","depois":"fio absorvível 3-0 para a musculatura, fio absorvível 3-0 para o tecido celular subcutâneo e fio não absorvível 3-0 para a pele."},"B":{"antes_md5":"6c2f940570916660676181374fdd571c","depois":"fio absorvível 5-0 para a musculatura, fio absorvível 5-0 para o tecido celular subcutâneo e fio absorvível 4-0 para a pele."},"C":{"antes_md5":"20ec3d5d679fc6cf50c9d9a0c660ffe4","depois":"fio não absorvível 3-0 para a musculatura, fio não absorvível 3-0 para o tecido celular subcutâneo e fio não absorvível 3-0 para a pele."},"D":{"antes_md5":"de08cb227a2f381aca6249e8ffb3c3ea","depois":"fio não absorvível 5-0 para a musculatura, fio não absorvível 5-0 para o tecido celular subcutâneo e fio não absorvível 4-0 para a pele."}}},{"id":"revalida_2022_1_q098","code":"REV-2022.1-Q098","campos":{"statement":{"antes_md5":"a36b90792739b614569bdd1362384a3f","depois":"Uma criança do sexo masculino com 10 meses de idade, previamente hígida, comparece à unidade de pronto atendimento com quadro de diarreia e vômitos há 2 dias, e oligúria há 1 dia, segundo relato da mãe. Ao exame físico, apresenta frequência respiratória = 55 incursões respiratórias por minuto, saturometria de 98%; auscultas cardíaca e respiratória sem alterações; frequência cardíaca = 140 batimentos por minuto; pressão arterial adequada; ausência de edema. Os exames laboratoriais mostram: sódio = 128 mEq/L, K = 4,8 mEq/L, bicarbonato = 13 mEq/L, ureia = 62 mg/dL, creatinina = 1,4 mg/dL, fração de excreção de sódio < 1%. Diante desse quadro, a conduta imediata mais adequada em relação ao paciente, após medidas de suporte e acesso venoso, é solicitar"},"A":{"antes_md5":"22c81e8cef995d2938b6cdb52734a298","depois":"expansão volêmica endovenosa com cloreto de sódio (NaCl) a 0,9%."},"B":{"antes_md5":"990b911324e669117e145ad6b0062d2c","depois":"aplicação endovenosa de bicarbonato de sódio a 8,4%."},"C":{"antes_md5":"e65819e89433f617b6f9d2a42a104de6","depois":"realização de tratamento de substituição renal."},"D":{"antes_md5":"5466d30323a46aed7b73de27b2969edf","depois":"aplicação endovenosa de furosemida."}}},{"id":"revalida_2022_1_q099","code":"REV-2022.1-Q099","campos":{"A":{"antes_md5":"785226e109def6173b3f3e77476338b1","depois":"situação cefálica, apresentação longitudinal, variedade de posição occípito-esquerda-posterior."},"B":{"antes_md5":"4825d99550cc3e5aed418b21e02866aa","depois":"situação cefálica, apresentação longitudinal, variedade de posição occípito-direita-posterior."},"C":{"antes_md5":"a23053d3f393f41a34bf28207b072ca3","depois":"situação longitudinal, apresentação cefálica, variedade de posição occípito-direita-posterior."},"D":{"antes_md5":"f824ad6800f31cb79e92a30ca5c3badf","depois":"situação longitudinal, apresentação cefálica, variedade de posição naso-esquerda-anterior."}}},{"id":"revalida_2022_1_q100","code":"REV-2022.1-Q100","campos":{"statement":{"antes_md5":"a1d973683dea74635f21c215ff608a32","depois":"Uma mulher com 32 anos de idade comparece à consulta médica agendada na Unidade Básica de Saúde levando o resultado de exame citopatológico do colo uterino coletado há 1 mês. A paciente, muito nervosa, confessa que havia lido o resultado do exame e que pesquisou na internet sobre o tema. Ressaltou que segue corretamente às orientações do seu médico e que, aos 29 anos de idade, realizou o mesmo exame, com resultado normal. O resultado do exame citopatológico do colo uterino realizado no último mês apresentou amostra satisfatória, representatividade da junção escamo colunar, presença de células escamosas e glandulares e presença de ASCUS – (células escamosas atípicas de significado indeterminado). Considerando o caso apresentado, após explicar à paciente que há presença de um exame com alteração, o médico de família deve"},"B":{"antes_md5":"fc723799882ad6f3a1316ca418830d20","depois":"solicitar novo exame citopatológico do colo uterino em 12 meses e, caso a alteração permaneça, avaliar indicação de cirurgia."},"C":{"antes_md5":"d204945bcb9d8ccd0477c0d3e7ab691e","depois":"encaminhar a paciente para o serviço especializado de Ginecologia para realização de um novo exame mais detalhado, a colposcopia."},"D":{"antes_md5":"a300db02c0b26389360a5022cc90424a","depois":"solicitar novo exame citopatológico do colo uterino em 6 meses e, caso a alteração permaneça, solicitar a realização de um exame mais detalhado, a colposcopia."}}}]$carga_dados$::jsonb;
  r jsonb;
  c record;
  q public.questions;
  v_statement text;
  v_options jsonb;
  v_atual text;
  v_situacao text;
  v_muda boolean;
  v_analises integer := 0;
begin
  perform set_config('sqie.reason', 'Texto fiel ao caderno oficial do Inep (carga das provas corrigidas, revisão de 12/10/2026)', true);
  for r in select value from jsonb_array_elements(v_dados) loop
    select * into q from public.questions x where x.id = r ->> 'id' for update;
    if not found then
      insert into _carga_texto_resultado values ('revalida-2022-1', r ->> 'id', r ->> 'code', '-', 'pulado: questão não encontrada no banco');
      continue;
    end if;
    v_statement := q.statement;
    v_options := q.options;
    v_muda := false;
    for c in select key as campo, value as v from jsonb_each(r -> 'campos') loop
      v_atual := case when c.campo = 'statement' then q.statement
                      else (select o ->> 'text' from jsonb_array_elements(q.options) o where o ->> 'id' = c.campo limit 1) end;
      if v_atual is not distinct from (c.v ->> 'depois') or md5(v_atual) is not distinct from (c.v ->> 'sem_tabela_md5') then
        v_situacao := 'já estava corrigido';
      elsif v_atual is not null and md5(v_atual) = c.v ->> 'antes_md5' then
        v_situacao := 'corrigido agora';
        v_muda := true;
        if c.campo = 'statement' then
          v_statement := c.v ->> 'depois';
        else
          v_options := (select jsonb_agg(case when o ->> 'id' = c.campo then jsonb_set(o, '{text}', to_jsonb(c.v ->> 'depois')) else o end order by n)
                        from jsonb_array_elements(v_options) with ordinality as x (o, n));
        end if;
      else
        v_situacao := 'pulado: o texto no banco mudou depois de 12/10/2026';
      end if;
      insert into _carga_texto_resultado values ('revalida-2022-1', q.id, q.code, case c.campo when 'statement' then 'enunciado' else 'alternativa ' || c.campo end, v_situacao);
    end loop;
    if v_muda then
      v_analises := v_analises + (select count(*)::int from public.question_analysis a where a.question_id = q.id and a.is_current and a.status = 'published');
      update public.questions set statement = v_statement, options = v_options where id = q.id;
      perform public.admin_log('question.updated', q.id, jsonb_build_object('status', q.status, 'reason', 'Texto fiel ao caderno oficial do Inep (carga das provas corrigidas, revisão de 12/10/2026)'));
    end if;
  end loop;
  insert into _carga_texto_resultado values ('revalida-2022-1', '-', '-', 'análises', 'análises publicadas que saíram do ar: ' || v_analises);
  perform set_config('sqie.reason', '', true);
end
$carga_texto$;

select resultado, detalhe from (
  select 0 as ordem,
         case when count(*) filter (where situacao like 'pulado%') = 0 then 'OK: ' else 'ATENÇÃO: ' end
           || 'Revalida 2022/1: '
           || count(distinct questao) filter (where situacao = 'corrigido agora') || ' questões corrigidas agora ('
           || count(*) filter (where situacao = 'corrigido agora') || ' campos); '
           || count(*) filter (where situacao = 'já estava corrigido') || ' campos já estavam corrigidos; '
           || count(*) filter (where situacao like 'pulado%') || ' pulados (de 397)' as resultado,
         max(situacao) filter (where campo = 'análises') as detalhe
  from _carga_texto_resultado where prova = 'revalida-2022-1'
  union all
  select 1, 'PULADO: ' || codigo || ' (' || campo || ')', situacao
  from _carga_texto_resultado where prova = 'revalida-2022-1' and situacao like 'pulado%'
) x order by ordem, resultado;
